-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[30102] = { id = 30102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hour of Twilight", description = "There's no need to stand around here forever. Have you forgotten? We can CONTROL TIME. Especially since you got rid of that Murozond fellow, back in the future.\n\nThat Dragon Soul that you just liberated? Thrall already has it, back in your present day. And he's going to need your help.\n\nYou ready to go?", completion = "You've arrived.\n\nGood, let us begin.", objectives = "Speak with Thrall at the Hour of Twilight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30103] = { id = 30103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Wyrmrest!", description = "The Dragon Soul... a weapon with enough power to defeat Deathwing. Thanks to you, it is now safely in our hands.\n\nCome! The aspects await us. We must bring the Dragon Soul to Wyrmrest Temple, in the center of Dragonblight.", progress = "Come, {name}. We do not have much further to travel.", completion = "I owe my life to you, heroes.\n\nNow that we hold the Dragon Soul safely within Wyrmrest, it may be that all of Azeroth owes their lives to you.", objectives = "Escort Thrall safely to Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30104] = { id = 30104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Documenting the Timeways", description = "You... {name}, was it? You assisted with our archival in the past. Well, technically it was the future, but I believe you understand. Time is highly relative.\n\nI require more information for our archive. While you and Nozdormu don't intend to overwrite this timestrand, as you did in the End Time, we can still benefit from more data.\n\nI require information on Captain Varo'then, one of Azshara's pretty little handmaidens, and... hmm... oh, how about that big felguard, just down those stairs?", completion = "We rarely enjoy the opportunity to employ a brave {class} like you. Our archive grows more thorough, thanks to your efforts.", objectives = "Slay a Legion Demon, a Royal Handmaiden, and Captain Varo'then, then allow Alurmi's Vessel to archive their information.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30105] = { id = 30105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Prophet", description = "The missive reads as follows:\n\n\"The Hour of Twilight is upon us. The world-shaman Thrall approaches Wyrmrest with the Dragon Soul in hand, feebly whimpering one final threat to destroy our glorious master.\"\n\n\"Stop Thrall, and we win our war. I will be watching you from nearby.\"\n\n   ~ The Twilight Prophet", progress = "I have my suspicions about this Twilight Prophet.", completion = "It is truly as we foresaw: Benedictus was the Twilight Prophet. And now he is no more.\n\nWe dealt a mighty bow to the Twilight's Hammer today. Let us hope that it was a deathblow.", objectives = "Find and unmask the Twilight Prophet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30106] = { id = 30106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deed is Done", description = "Prince Wrathion will be pleased to hear that you've succeeded. You should report back to him at Ravenholdt Manor.\n\nThe Prince has been known to be extremely generous to those who help him.", completion = "That's wonderful news, {name}. Creed was not the most powerful of the remaining black dragons, but his manipulation of the Gilneans was truly diabolical.\n\nI've prepared a reward for you. These blades may not look like much at present, but in the right hands they may yet awaken.\n\nPerhaps in YOUR hands...", objectives = "Report your success to Prince Wrathion at Ravenholdt Manor in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30107] = { id = 30107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cluster Clutch", description = "The daggers I have given you are lifeless shells. They can do great things, once they are given a means to contain the power I have in mind.\n\nI need for you to acquire Shadowy Gems for me. The facets of these unusual stones are like windows into the infinite. They are often used by minions of the Twilight's Hammer to control the most powerful of elementals.\n\nA great battle is raging around Wyrmrest Temple. Collect Elementium Gem Clusters from Deathwing's minions and bring the gems to me.", progress = "How many gems have you collected?\n\nAre my father's minions as twisted as he?", completion = "Ah, do you see how they shimmer? Many fine gems sparkle in the light, but only these seem to sparkle with darkness.\n\nI'll perform an enchantment on these while you are on your next mission.\n\nAre you ready?", objectives = "Collect 333 Shadowy Gems by looting Elementium Gem Clusters from creatures in the Dragon Soul Raid encounter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30108] = { id = 30108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Man in Karazhan", description = "Your next target is the Black Dragon Nalice, who is engaged in some sort of arcane debauchery beneath the ruined tower of Karazhan.\n\nYour primary mission is to destroy her, but if you can bring me back a vial of her blood, I'll be able to use it to augment the power of the daggers I've given you.\n\nYour accomplice Zazzo has already been dispatched to the scene and awaits you there. He'll have more details.", completion = "Madness. Insanity!\n\nI don't know what Nalice is up to down there, but the entire basement radiates with diabolical arcane energy. She's got an entire cult worshipping her as a goddess.\n\nIf we're going to take her out, we have to do it soon. I hope you're ready for this!", objectives = "Report to Zazzo Twinklefingers in the ruins just southeast of Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30109] = { id = 30109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Betrayer", description = "I've pinpointed Nalice to the Master's Cellar, an extended basement you'll find in the ruins up ahead.\n\nDragon cultists are everywhere, and Nalice has set up some strange arcane storage devices throughout the area. Perhaps you can use those to your advantage?\n\nSneak past the cultists, obliterate Nalice, and grab a vial of her blood for Wrathion.\n\nI'll keep my eyes on you and pull you out if you get into any trouble. But I'm NOT coming in there with you!", progress = "Nalice. Dead?", completion = "You did it? She's dead? Unbelievable! You're some kind of miracle-worker!\n\nHere, let me see that blood. I can preserve its energies in an arcane matrix for your trip back...", objectives = "Sneak into the Master's Cellar in the ruins around Karazhan, defeat Nalice, and acquire a Vial of Black Dragonsblood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30110] = { id = 30110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Cataclysm - Raid Finder - 1st" }
quests[30111] = { id = 30111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Cataclysm - Raid Finder - Nth" }
quests[30112] = { id = 30112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Score to Settle", description = "Utgarde's forces are organizing under the advisory of Prince Keleseth, a san'layn ambassador of the Scourge.\n\nWe cannot allow the vrykul to benefit from his counsel any further. Silence him.", progress = "Is it done, {name}?", completion = "Revenge feels good.  To think that this is but a taste of what's to come.\n\nArthas will get what he deserves soon enough.", objectives = "Dark Ranger Marrah wants you to slay Prince Keleseth inside Utgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30113] = { id = 30113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in the Depths", description = "<Zazzo performs an enchantment on the vial of blood, then quickly hands it back to you, as though it's toxic.>\n\nDone! You'll want to get this back to Wrathion as soon as possible, along with those two daggers of yours.\n\nI don't know what he plans to do with this stuff. Between you and me, sometimes that little dragon kid creeps me out. Good luck!", progress = "Ah, you've returned! I no longer sense Nalice's presence. Is she dead? Or has she somehow eluded us both?", completion = "You are, indeed, a master of your craft. Nalice is dead, and it is time you are rewarded for your efforts.\n\n<Wrathion takes the vial from you, his face a mask of equal parts reverence and revulsion. He drops the gems you collected one-by-one into the blood, muttering an incantation.>\n\n<Without warning he pours the blood over the blades of the daggers, and the steel seems to writhe and twist as though alive. When the smoke clears, the daggers have altered their shape.>", objectives = "Take the Vial of Preserved Dragonsblood, along with your daggers Fear and Vengeance, to Wrathion at Ravenholdt Manor in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30116] = { id = 30116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharpening Your Fangs", description = "Do you understand why I have you assassinate the dragons, yet spare the mortals? It isn't their fault. They must seek out their own destiny, free from the meddling of my kind.\n\nWe are nearing the end of our mission, and it is time for you to seek out your own destiny as well. I can continue to augment your weapons, but collecting shadowy gems won't be enough. My work will require entire clusters. Gather them from my father's minions...", progress = "How many clusters have you acquired?\n\nThe tenacity of your race continues to inspire me!", completion = "You have done it! No doubt you placed yourself and your allies in great peril to acquire these. Your sacrifices will be rewarded in time. I will use these as the foundation of a powerful enchantment for you.\n\nBut we will need one additional catalyst. Are you ready for your final and most dangerous mission, {class}?", objectives = "Collect 60 Elementium Gem Clusters from creatures in the Dragon Soul Raid encounter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30117] = { id = 30117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoneplow Thirsts", description = "Excuse me... {name}? Did I hear your name correctly?\n\nI've come from Stoneplow, in the west. They sent me to pick up some emergency beer rations, but the Stormstout Brewery is all boarded up!\n\nIt looks like your handsome friend there - no, not Mudmug, the other one - has a few casks with him. Could you spare a keg for a town in need?", progress = "Greetings, {class}.", completion = "Finally! Emmi's come through.\n\nI hope all is well at the Stormstout Brewery. My men don't do well without beer.", objectives = "Deliver a cask of The Emperor to Loon Mai at Stoneplow in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30118] = { id = 30118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patricide", description = "Your next target has claimed the lives of all of my other assassins. I need you to kill my father himself.\n\nYou must destroy Deathwing.\n\nWe are out of time. His madness has already corrupted all the others of my kind, and his darkness will consume the world if he is not stopped.\n\nIf you by some miracle succeed, and can retrieve for me a piece of him - perhaps a fragment of the armor he uses to disguise his true chaotic nature - the reward I give you will be without equal.", progress = "What of my father?", completion = "I can feel it - like a dark shadow lifted from the land. Dead. My father is dead!\n\n<Wrathion takes the jaw fragment from you. His hands and face blur as he recites a dark enchantment, the gem clusters you collected earlier orbiting around his head. The jawpiece suddenly shatters, and with a terrible hissing sound your twin daggers awaken.>\n\nYour reward is ready. Take them, quickly. You will need them momentarily...", objectives = "Destroy Deathwing and retrieve a Fragment of Deathwing's Jaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30119] = { id = 30119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well of Eternity RP Tracker", description = "I am duty-bound to look into your claims immediately, {race}, which means my mission here now must fall to you.\n\nA surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development.\n\nA bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame.\n\nYou must find a way to interrupt the ritual and reclaim the world tree's branch.", sourceObjective = "Recover the Branch of Nordrassil from the Firelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[30120] = { id = 30120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Drak'Tharon", description = "'Ey, mon, you be here! Dis is good, mon!\n\nDrak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. In return for your help, the keep's most valuable treasures be yours, mon!\n\nOnce ya be reachin' its top, ya must summon me, and I'll perform the ritual.\n\nAlas, my summonin' will be comin' at a cost. Ya must collect mojo from the survivors.", completion = "We done a great thing, mon! And dis just be da beginning....\n\nSeek me out in Zul'Drak when da time be right.\n\nDere be a war to be won, mon!", objectives = "Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30121] = { id = 30121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search Party", description = "I sent a diplomat to look for allies in the ruins east of here.\n\nMy diplomat has not returned and now Kang tells me this jungle is filled with a sinister people known as the mogu.\n\nChezin is my friend and Leza's brother. To lose a brother would cause her to give in to despair. She already has enough to worry about with her fever.\n\nCould you investigate the ruins east of here and find out what happened?", completion = "P... poison. Need... warn... Dezco...", objectives = "Search the Krasari Ruins for Chezin Dawnchaser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30122] = { id = 30122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Filigree Flask", description = "You have found a beautiful silver flask decorated with ornate filigree.  With the right materials and your skill in alchemy, it could become quite magical.", objectives = "Fill the vial with a potent alchemical mixture.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30123] = { id = 30123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skitterer Stew", description = "Leza has a fever. No mother in labor should have a fever.\n\nMama Bramblestaff once told me that Skitterer Stew could heal almost any illness. Let us put this knowledge to the test.\n\nGather some intact skitterer glands for me while I get the herbs we'll need and I'll whip up a batch.", progress = "Even the jungle air is alive with danger.", completion = "Excellent! Nothing clears a sickness like Skitterer Stew.\n\nHere, take this. It's a little memento of Mama Bramblestaff.", objectives = "Gather 5 Intact Skitterer Glands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30124] = { id = 30124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Them!", completion = "Well done, {name}. You have performed admirably and bought us some time to fortify our defenses. Now if I can just get Dezco to go on the offensive.", objectives = "Kill the Darnassian Outrider.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30125] = { id = 30125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profit Mastery", description = "Two words: Tiger Blood!\n\nThis is gonna sell better than saronite back on the black market. Especially once I finish spreading a rumor about how it makes you all buff and stuff.\n\nThing is, I ran out of ammo. Can you round up a few vials of tiger blood for me? I'll cut you in on the scam.", objectives = "Obtain 12 Vials of Tiger Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30126] = { id = 30126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crane Mastery", description = "Thing about hunting birds is you need ammo - and I ain't got any. Thing about hunting with Nesingwary is you need to prove you can keep your tally and bragging rights up.\n\nCan't hunt, can't brag. And I like bragging so this is no good.\n\nCan I hire you to go kill me some carp hunters? You'll find them up and down the river west of here.", objectives = "Kill 8 Carp Hunters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30127] = { id = 30127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat from Dojan", description = "Mogu? They seem like the elves, ancient and an over developed sense of entitlement. Everyone of Azeroth must learn, sooner or later, that the Horde is not \"visiting\" this world. We are here. We are staying.\n\nTeach them this lesson. Quell their numbers in the ruins south and west of here. Break their amassing forces before they decide to attack.\n\nLearn what you can of how these creatures fight, and how they die.", progress = "You found how many? Sounds like a veritable nest of the vile creatures. If they were more civilized I might consider extending them an invitation to join the Horde.", completion = "These are more than just a bandit threat. They are an ancient people beginning to rally under a single banner. Mark my words, soon these lands will know war.", objectives = "Kill 6 Dojani Reclaimers and 8 Dojani Surveyors, and 4 Dojani Enforcers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30128] = { id = 30128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pools of Youth", description = "The mogu found the Pools of Youth!\n\nMama Bramblestaff used to tell me old stories about those. During the mogu empire they would use the waters to extend life.\n\nThing is those stories never ended well for some reason. As if the waters were cursed.\n\nEither way, we should investigate. There is a good chance those waters might help Leza.\n\nIt looks like the Pools of Youth are on the northwestern side of the ruins.", progress = "Leza's pain is immense. Only powers beyond my own can save her and the baby now.", completion = "At this point I am willing to try anything. This land is claiming my wife and unborn child. I need all the help I can get.", objectives = "Recover water from the Pools of Youth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30129] = { id = 30129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mogu Agenda", description = "Mogu don't often gather in numbers like this. We should find out what they are up to.\n\nI thought I heard someone shouting orders near the center of the ruins.\n\nWe should probably see if he has information.", progress = "The mogu once ruled as emperors, subjugating all races they encountered.\n\nIt would seem these particular mogu have aspirations of reliving the past.", completion = "Wait. This document talks about the Pools of Youth!\n\nThe pools exist?!", objectives = "Recover the Dojani Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30130] = { id = 30130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herbal Remedies", progress = "I've been punched, stabbed, thrown off of a cliff, hit in the face by someone's mace, hit in the face by my own mace, and fell off the elevator at Thunder Bluff on more than one occasion.\n\nNone of that pain sounds even half as bad as what Leza is going through. I hope this tea helps...", completion = "Thank you hero. Kor is a brave warrior but he lacks compassion at times. Life must come before death, or there will be none of us left when the fighting is done.", objectives = "Find 20 Imperial Lotus Leaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30131] = { id = 30131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life", description = "My child is coming. I must help as I may.\n\nStay nearby, hero. If my wife and child survive, I would have them look on the face of the one who saved them.", progress = "I pray to An'she that my wife and child survive this journey.", completion = "She... she died. For all the powers the Light has given me, I was unable to save her.\n\nThanks to your help, however... we saved my sons.", objectives = "Speak with Sunwalker Dezco, and wait for the newborn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30132] = { id = 30132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going West", progress = "War. It always comes down to war.", completion = "{name}! Well timed!\n\nWe were laying an ambush for the Alliance in the ruins west of here when the mogu ambushed us. They are using mage portals to call in reinforcements.", objectives = "Find the Sunwalker Scout near the Crane Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30133] = { id = 30133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Wilds", description = "Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers.\n\nThey should be told of what happened here.\n\nIf you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone north. When you reach the temple, find Koro Mistwalker.", completion = "I see... And the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Watch, I have to implore you to help us deal with them here.", objectives = "Locate the missing Zhu's Watch Courier in the northern area of the Dojani River, then continue on to the Temple of the Red Crane and speak with Koro Mistwalker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30134] = { id = 30134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Things", description = "Welcome to the Order of the Cloud Serpent, {race}. I can see from the spark in your eye that you wish to join the Order.\n\nLet me get a good look at you.\n\n<Elder Anli gently holds your head and gazes at your face.>\n\nHmm. I see honesty and earnestness in your heart. You have journeyed far to come here, but I am afraid you must go yet further.\n\nYour path into the Order begins now.\n\nSpeak to Instructor Tong at Windward Isle to the northeast to take the first step.", completion = "Thank goodness, they finally sent someone!\n\nThings have gotten out of control!", objectives = "Find Instructor Tong at Windward Isle in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30135] = { id = 30135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating the Odds", description = "At first, the Slitherscale were too frightened to approach the wild serpents.\n\nThen, I caught them snatching the eggs under the cover of night.\n\nNow, they are slaughtering adults and hatchlings alike!\n\nIf we do not do something, these gentle creatures will be completely wiped out. Then there won't even be an Order of the Cloud Serpent to join!\n\nGo and slay these vile Slitherscales, and then we will talk.", progress = "The Order rarely meddles with the natural balance on this island, but it is too important to save the serpents.", completion = "Thank you, {race}.\n\nI tried to stop the Slitherscale where I could, but I was no match for their numbers.\n\nYour work today will help preserve an entire generation of cloud serpents.", objectives = "Kill 8 Slitherscale Rippers or Slitherscale Eggdrinkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30136] = { id = 30136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empty Nests", description = "When the attacks began, the young hatchlings scattered in terror.\n\nThey are roaming around the island, lost and scared.\n\nIf you want to help, take this rope and leash the lost little ones. Take them back to their nests. Return them home.", progress = "Did you return the hatchlings to their nests?", completion = "Don't worry. The hatchlings will be safe inside their nests.\n\nI can't thank you enough for arriving when you did.", objectives = "Leash and return 6 Windward Hatchlings to their nests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30137] = { id = 30137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Collection", description = "Ahhh, I should have known! You have the look of a hungry initiate.\n\nI would gladly help you choose a serpent egg, but the Slitherscale have thoroughly raided the cloud serpent nests.\n\nI'm terribly sorry. I don't know what to tell you.\n\nUnless you're crazy enough to sneak into the saurok camp to the east and retrieve some stolen cloud serpent eggs, I'm afraid I can't help you.", progress = "The saurok keep the stolen serpent eggs in their camp.", completion = "Oh, wonderful!\n\nThese eggs look...well...they look a little on the small side. Are you sure you couldn't find any better ones?\n\nOh well, I suppose with the current situation, we can't be so picky.", objectives = "Collect 6 Serpent Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30138] = { id = 30138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choosing the One", description = "I have examined each egg, {name}. Out of the lot that you brought me, I have chosen the three eggs with the most promise.\n\nYou may choose only one egg to take with you. Are you ready to make your final selection?", completion = "You may choose only one egg to take with you.\n\nChoose carefully. There is no going back.", objectives = "Speak to Instructor Tong at Windward Isle in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30139] = { id = 30139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", progress = "The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", completion = "Ah yes, Elder Anli mentioned that a new student had joined our ranks. I see you have already chosen your cloud serpent egg.\n\nI will instruct you on its care. Let me see it for a moment.", objectives = "Return to Instructor Skythorn at the Arboretum in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30140] = { id = 30140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", progress = "The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", completion = "Ah yes, Elder Anli mentioned that a new student had joined our ranks. I see you have already chosen your cloud serpent egg.\n\nI will instruct you on its care. Let me see it for a moment.", objectives = "Return to Instructor Skythorn at the Arboretum in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30141] = { id = 30141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", progress = "The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", completion = "Ah yes, Elder Anli mentioned that a new student had joined our ranks. I see you have already chosen your cloud serpent egg.\n\nI will instruct you on its care. Let me see it for a moment.", objectives = "Return to Instructor Skythorn at the Arboretum in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30142] = { id = 30142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's A...", description = "Oh my! This egg is going to hatch at any second!\n\nWell, looks like this little guy is eager to meet you.\n\nAre you ready?", progress = "What a proud moment for you!", completion = "Congratulations! It's a beautiful hatchling of your own.\n\nPlease take care of it, {name}.", objectives = "Watch your egg hatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30143] = { id = 30143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Grow Like Weeds", description = "Ahh, it is you again, {name}.\n\nInstructor Windblade is looking for you. You can find her on the ridge to the east.\n\nShe has some news about your cloud serpent.", progress = "You are doing well, trainee.", completion = "Congratulations, {name}.\n\nThere is great joy in seeing the fruits of your own labor.", objectives = "Speak to Instructor Windblade at The Arboretum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30144] = { id = 30144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training: Ring Round-Up", description = "Now that your serpent is fully grown, you are ready to begin flight training.\n\nAs with all novices, you must start at the beginning.\n\nYour first task is simple. Fly through 6 of the cloud rings between the spires to the east.", progress = "How did your first flight go?", completion = "What have you learned from this lesson?\n\nSpeed. It's all about speed.", objectives = "Fly through 6 cloud rings while riding your cloud serpent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30145] = { id = 30145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training: Full Speed Ahead", description = "The next task will be a little harder.\n\nAre you ready?", progress = "I hope I do not need to question your dedication.", completion = "You did better than I expected. Not bad for a new trainee.", objectives = "Follow Instructor Windblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30146] = { id = 30146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snack Time", description = "Cloud serpents love to eat, and one of their favorite treats is the sugar minnow.\n\nThese fish can be found in salt or fresh water anywhere in Pandaria. I trust you have some skill in fishing, and your own fishing pole to catch them?\n\nBring me a fresh catch and I'm sure the hungry beasts around here will be very grateful.", progress = "Did you find a good place to fish?", completion = "Oh wonderful! These fish will do nicely.", objectives = "Fish 10 Sugar Minnow from any fresh or salt water in Pandaria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30147] = { id = 30147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of the Past", description = "The Order of the Cloud Serpent's history stretches back thousands of years, and although we have tried to preserve the old ways, there are ancient techniques that have been lost over time.\n\nYou can help us recover some of this knowledge by searching Pandaria's dig sites for clues to our past.\n\nUse your archaeology skill to survey around Pandaria and bring me whatever you find.", progress = "How did the excavation go?", completion = "Amazing, {name}. These relics are invaluable to our studies. We will learn much from these fragments.", objectives = "Visit archaeology dig sites around Pandaria and use your survey ability to retrieve 6 Serpentrider Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30148] = { id = 30148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Flesh Wound", description = "Many of the baby hatchlings at Windward Isle have been injured as a result of all the fighting.\n\nI have been told that you may be able to help them, with your access to powerful bandages.\n\nPlease go northeast and use some of the best bandages you can acquire to save the injured hatchlings.", completion = "Wonderful! It is a good thing you are trained in the arts of first aid.", objectives = "Use Windwool Bandages or Heavy Windwool Bandages to heal 8 Injured Hatchlings at Windward Isle. These can be made by Tailors or bought on the Auction House.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30149] = { id = 30149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Feast for the Senses", description = "I have heard that you know a thing or two about cooking.\n\nAs it so happens, serpents love to eat Fish Cakes.\n\nIf you use your culinary skills and bring me 5 of these dishes, the cloud serpents around here will be very happy.", progress = "Were you able to find the necessary ingredients?", completion = "Oh these do look quite delicious. You are quite the cook!", objectives = "Collect 5 Fish Cakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30150] = { id = 30150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet as Honey", description = "<The hatchling scampers about, then whines and whimpers.>\n\nFrom the cloud serpent's behavior, you have a hunch that it wants a sweet treat.\n\nThe fragrant trees in The Arboretum are home to many honey hives.\n\nIt will be a simple matter to collect combs from the nearby honeykeepers.", progress = "<The hatchling spins around in glee as you return.>", completion = "The hatchling leaps for your hand. It winds its long, serpentine tail around you and begins to lick the honey from your fingers.\n\nThat tickles!", objectives = "Collect 30 Honeycomb from Angry Honeykeepers in The Arboretum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30151] = { id = 30151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch!", description = "<The hatchling looks up at you with a bored, listless expression.>\n\nYou have a feeling the serpent is tired of being cooped up all day.\n\n How about playing a little game of catch?", progress = "<The serpent watches you curiously.>", completion = "Oh my, I see you and your serpent are having a great time! Well done, {name}. Playtime will greatly increase your serpent's mental and physical acuities.", objectives = "Use the Bouncy Ball. Then, catch and return the ball to your hatchling 8 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30152] = { id = 30152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sky Race", description = "The time for the great race is upon us!\n\nTraverse the course among the spires and pass through the checkered flags on each of the 10 balloon checkpoints.\n\nMake sure to pass underneath the finish line when you are done.\n\nThe competition will be fierce, but I wish you luck. Speak to me when you are ready to begin.", completion = "Wonderful! How does it feel to finish the Sky Race?\n\nYou must be eager to collect your prize!", objectives = "Complete the Sky Race by flying through 10 checkpoints, then passing underneath the Finish Line at The Arboretum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30153] = { id = 30153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full Speed Ahead", description = "It is time for our training session.\n\nFollow me around the spires. Let's see if you can keep up while staying mounted.", objectives = "Follow Instructor Windblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30154] = { id = 30154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Easiest Way To A Serpent's Heart", description = "<The hatchling scowls at you.>\n\nUh-oh, looks like someone is in a bad mood today!\n\nLuckily, you know just the thing that will cheer up the little beast.\n\nCloud serpents love the taste of tiger meat, but the tender flanks can be... challenging... to acquire.\n\nLuckily, you recall there are some fat, juicy tigers to the northeast, on Windward Isle.\n\nSure, you might suffer some scratches and a little mauling, but it's all worth it for your serpent, right?", progress = "Looks like the task is done.", completion = "I see you have been hard at work, gathering food for your hungry little serpent. Well done. It may not seem worth it now, but your serpent will know of your efforts, and it will love you for it.", objectives = "Collect 5 Tiger Flanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30155] = { id = 30155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring the Balance", description = "The situation at the islands remains dire, {name}.\n\nThe Slitherscale saurok have not responded to our attempts at peace, so only one option remains.\n\nIn order to protect the wild cloud serpents, we must rid the island of their presence. Only then can the cloud serpents be left to live in peace.", progress = "The poachers will wipe out the cloud serpents completely if they are not stopped.", completion = "If the poachers will not listen to diplomacy, then they will surely listen to our blades. Thank you, {name}.", objectives = "Kill 8 Slitherscale Rippers or Slitherscale Eggdrinkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30156] = { id = 30156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding Time", description = "<The serpent darts forward and bites your fingers.>\n\nOuch! It seems, without a doubt, that the little beast is hungry. You recall that some meaty-looking turtles can be found on the wild cloud serpent island to the northeast.\n\nPerhaps some turtle meat will fill the hatchling's voracious appetite.", progress = "<The serpent looks at you with hungry eyes.>", completion = "You are learning well, young trainer. Saltback meat is tough, but loaded with the nutrients that a young hatchling needs to grow.", objectives = "Collect 3 Saltback Meat and feed them to your hatchling companion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30157] = { id = 30157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emptier Nests", description = "Oh, thank goodness, another cloud serpent trainer!\n\nI just received word that the wild hatchlings at Windward Isle to the northeast are in serious trouble!\n\nWhile the adults fight those terrible saurok, who is watching the cute little babies? No one, that's who!\n\nWE HAVE TO SAVE THEM!\n\nI'm sending every trainer I can find to go and help. If you aren't too busy, can you make sure the hatchlings are safely delivered back to their mothers' nests?", completion = "I see you have been taking good care of the young hatchlings out there. Well done.", objectives = "Leash and return 6 Windward Hatchlings to their nests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30158] = { id = 30158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarming the Enemy", description = "If we are to stop the poachers, we need to take more aggressive action.\n\nIf we can remove the enemies' primary tools for killing and capturing serpents, we may be able to stop their operation altogether.\n\nI need you to go into their territory on the eastern end of Windward Isle and steal their weapons.\n\nA cat without claws cannot strike.", progress = "Is it done?", completion = "We have weakened them, but we cannot celebrate completely. A toothless tiger still has claws.", objectives = "Collect 5 Slitherscale Harpoons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30159] = { id = 30159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preservation", description = "Oh no! We must stop them! {name}, is it? The Order needs your help!\n\nDo you know what those horrible Slitherscale saurok are doing?\n\nThey have the audacity to steal cloud serpent eggs straight from the matriarch's nests!\n\nWhile the cloud serpents become ever rarer, those brutes are... are...\n\n<Suchi takes a deep breath.>\n\n...they're eat their eggs for dinner! It's horrible!\n\nGo to Windward Isle to the northeast and recover any unbroken eggs that you can. As students of the Order, it's our duty!", progress = "Will those nasty Slitherscale saurok never give up?", completion = "Well done, {name}. As soon as Suchi told me she sent you to recover the stolen eggs, I knew you would accomplish the task.\n\nOur instructors will make sure to return these eggs to a safer place.", objectives = "Collect 8 Stolen Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30160] = { id = 30160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Ella", progress = "Why {name}, it's nice to see you again.", completion = "Oh, is this for me? I-I don't know what to say.\n\nIt's very pretty, thank you!" }
quests[30163] = { id = 30163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Tribe", description = "We fell back to the refuge when the mogu attacked but lost a number of our people along the way.\n\nTravel west and north of here and look for any captives you can rescue that could help us in our fight.\n\nLeave any Alliance you find to their fate.", progress = "Hellscream's eyes upon you.", completion = "We've already lost so many. I refuse to lose any more.", objectives = "Rescue 8 Dawnchaser Captives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30164] = { id = 30164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stoneplow Convoy", description = "I tried to save as many of the Stoneplow envoys as I could but these \"mantid\" dragged many of them off into the jungle.\n\nThese are civilians in need of our help.\n\nPlease take the herbs you gathered earlier. I've infused them with what gifts of the Light are still granted me. Use them on as many of the Stoneplow envoys as you can.", progress = "A sunwalker's first duty is to preserve and protect life.", completion = "The civilians are trickling in thanks to you. These \"mantid\" creatures are a serious threat. We will need to rally our forces soon to help.\n\nOne of the envoys asked me to give this to you as a token of thanks.", objectives = "Use Imperial Lotus Poultice on 7 Stoneplow Envoys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30165] = { id = 30165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Picked Blue Serpent" }
quests[30166] = { id = 30166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Picked Green Serpent" }
quests[30167] = { id = 30167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Picked Gold Serpent" }
quests[30168] = { id = 30168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Raiders", description = "Saurok!\n\nThese vile creatures are obsessed with killing and stealing. They attacked our settlement without provocation or warning.\n\nPlease, {class}, can you aid us?\n\nHelp us recover our lost possessions from these Riverblade raiders that march along the river and we will gladly reward you.", progress = "I think they even stole my holy spittoon.", completion = "Not many would stop to help a village in need... especially so deep in the wilds.\n\nYou are a champion to our people, {name}.", objectives = "Recover 5 pieces of Pillaged Jinyu Loot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30169] = { id = 30169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Leader Slovan", description = "The raiders are led by a particularly violent saurok known as Slovan. The Crane Temple usually comes to our aid when he attacks but now we find ourselves outmatched and outmaneuvered.\n\nPlease, {class}, aid us by destroying this raid leader.\n\nYou can find him in his den behind the Krasari Falls.", progress = "Slovan has always been a nuisance, but with the Crane Temple's defenses down he has become a true threat.", completion = "You have done us a great service today. On behalf of my people I thank you.\n\nPlease, accept this token of our gratitude.", objectives = "Kill Slovan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30172] = { id = 30172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barreling Along", description = "No, no, no, don't you worry about pickin' 'em up. I can hold these here barrels.\n\nI may not be the handsomest pandaren, or the smartest, or any fun to be around in the slightest, but I'm stronger than a mushan beast.\n\nI'mma just need you to lead the way.", progress = "Where's Mudmug?", completion = "Good! The water's here!", objectives = "Lead Mudmug back to Halfhill.\n\nIf you become separated from Mudmug, you can find him next to the giant banana in the Gilded Fan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30173] = { id = 30173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Pigs!" }
quests[30174] = { id = 30174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Family", description = "Kor should have caught up by now. He said he was going to secure the Ruins of Korja east of here and meet us to help with the mantid threat.\n\nHe may need help against Groundbreaker Brojai. Could you assist him? Kang and I will follow shortly.", progress = "This land claims so much.", completion = "I thank you for avenging my friend, {name}. We did not always see eye to eye, but I will mourn him.\n\nI know he would have wanted you to carry one of his items with you as a token of his memory and gratitude.", objectives = "Search for Kor Bloodtusk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30175] = { id = 30175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mantid", description = "The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that.\n\nNow they are preparing to hit Stoneplow.\n\nPlease, {class}, destroy some of these beasts before they get sufficient numbers to flank our home.\n\nIf my cousin, Ambassador Len, is still alive and at our convoy he should be able to reward you for your help.", progress = "It has been many thousands of years since mantid were seen on this side of the Great Wall.", completion = "Thank you for your help, {class}! I've never seen anybody stand up to the mantid like that before.\n\nWell, other than the Shado-Pan, of course...", objectives = "Kill 10 Ik'thik Precursors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30177] = { id = 30177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Heroic Random (1st) (Cataclysm)" }
quests[30178] = { id = 30178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Wilds", description = "Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers.\n\nThey should be told of what happened here.\n\nIf you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone south. When you reach the temple, find Koro Mistwalker.", completion = "I see... And the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Watch, I have to implore you to help us deal with them here.", objectives = "Locate the missing Zhu's Watch Courier in the southern area of the Dojani River, then continue on to the Temple of the Red Crane and speak with Koro Mistwalker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30179] = { id = 30179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poisoned!", description = "The... mogu. Do not trust. Poison. Get sample... sample blades. Bring to Dezco... in Thunder Cleft, west of here.", progress = "You have news of Chezin?", completion = "Chezin is dead? This is very bad news indeed. Kor, Chezin and I have fought dragons, undead, and Alliance on nearly every shore that has a name.\n\nTo lose him like this...\n\nThank you for recovering these weapons. It should teach us much about our new enemy.", objectives = "Gather 5 Mogu Poisoned Blades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30180] = { id = 30180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Labor for Labor", description = "My wife, Leza, is going into labor but she is very very sick. I need to keep her warm but we've exhausted our supply of dry firewood.\n\nCould you grab some twigs and branches from the nearby trees for me? Time is of the essence!", objectives = "Gather 8 pieces of Fire Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30181] = { id = 30181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushan Mastery", description = "Mushan! Would ya look at the size o' 'em. Old as the dirt they walk on probably. A fine trophy.\n\nIf you are lookin' to test your mettle as a big game hunter, start with them.", progress = "They didn't send ya' runin' did they?", completion = "Well done {name}.\n\nMy father travels across the sea to a new continent and all he can seem ta' want to hunt is old borin' wolves.\n\nMe, I like to hunt stuff with meat on its bones.", objectives = "Kill 15 Dustback Mushans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30182] = { id = 30182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fox Mastery", description = "So, when I was scouting east of here I saw a collection of foxes. That's what I first learned to hunt when back on the Wandering Isle.\n\nIf you want to see the challenge a young pandaren hunter faced when growing up, head east and face off against a bunch of foxes. They tend to be clever and cunning so be on your guard.", progress = "I used to go on fox hunts with my father. If he could see me now! Hunting in Pandaria!", completion = "Well done! You outfoxed the foxes. I will talk to Mr. Pleeb about getting you another trophy made.", objectives = "Kill 15 Sly Foxes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30183] = { id = 30183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalker Mastery", description = "Tigers! No matter what land I go to I hear about these big fanged beasts. And yet I haven't had a chance to hunt any of them.\n\nLet's go hunt some tigers. I'll go east, you go west. I think I saw some near Dustback Gorge. I'm sure there are tons near those mushan.", progress = "What's your count up to?", completion = "Wow! You really racked up a count. I'll chat with Mr. Pleeb about getting the best one converted to a trophy for you.", objectives = "Kill 15 Gorge Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30184] = { id = 30184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushan Mastery: Darkhide", description = "My boy here is a talented hunter... in training. Let's show him an old 'Nessy style hunt shall we?\n\nI saw a mighty big mushan east of here with a hide dark as night. It looked like it had taken down a number of hunters in its day.\n\nIf you want a big game hunt, go try an' take it on.", progress = "Puttin' the \"big\" into \"Big Game Hunter.\"", completion = "Now that's a proper trophy right there.", objectives = "Obtain Darkhide's Head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30185] = { id = 30185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortoise Mastery", description = "Granted, tortoises are not big game but they can be mean game. They also work as the perfect bait for bigger game!\n\nGotcher found some ol' tablets sayin' that the Torjari Pit is a sacrificin' site. The old empire used ta' feed unruly sorts to the waters as it were.\n\nWell ah mean to see me what's down in that water. Gather up some fresh tortoise shells and meet me at the pit.\n\nLet's see if ol' legends be true.", progress = "I've always been livin' in me father's shadow. But after today, folks are gonna remember the name of Nesingwary, Jr.!", completion = "Thank ye. This one aught ta' one up me pop.", objectives = "Gather 5 Intact Tortoise Shells.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30186] = { id = 30186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parental Mastery", description = "If them tablets were correct, all ay got ta do is a small dance ritual and the big thing o' the deep will be summoned.\n\nWhen it comes out, we'll get 'em and show me pop we are both true big game hunters like him.", progress = "Now that is how ya big game hunt.", completion = "You saved me son! I canno' ever thank ye enough. Please! Take this fer your efforts.", objectives = "Destroy Torjar's Bane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30187] = { id = 30187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training: In Due Course", description = "Now that you have learned the basics of the race, you should go learn the course.\n\nExplore the spires and collect a race flag from each of the checkpoints.\n\nFly through each checkered flag to collect it.", progress = "Do you have what it takes to compete... and win?", completion = "Well done. If you hadn't been capable of finding the checkpoints, I fear you would never have done well in the Sky Race.", objectives = "Fly through 10 Race Flags at the Checkpoints floating above the Mistveil Sea.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30188] = { id = 30188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Skies", description = "I can no longer call myself your teacher, {name}.\n\nYou have proven yourself worthy of your cloud serpent.\n\nToday, you shall join our ranks. Are you ready?", completion = "Today, we become brethren. Congratulations on joining the Order of the Cloud Serpent. Let us ride together!", objectives = "Join the Order of the Cloud Serpent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30189] = { id = 30189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Ella", progress = "How are you today, {name}?", completion = "Really? For me?\n\nSuch a lovely apple shouldn't be eaten alone.\n\nHere, please have half." }
quests[30190] = { id = 30190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprite Plight", description = "Sprites again! I hate these things. We need to stop them before they hurt someone or burn down half of the village!\n\nIf you see any of the pests, please deal with them!", completion = "We need to figure out where these things are coming from. We're dealing with this near daily and it's getting out of hand.\n\nThank you for your help.", objectives = "Kill 8 Slateskin Troublemakers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30191] = { id = 30191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steer Clear of the Beer Here", description = "Someone left some beer out up on the southern rise and now the sprites have developed a taste for our brew. They've been sneaking into town all morning, stealing whatever kegs they find.\n\nBring back what you can. A pandaren worker without brew is just... it won't be very productive. We need the men in good spirits.", progress = "Did you find any of the stolen kegs?", completion = "The workers will love you for this!", objectives = "Recover 10 Stolen Mistfall Kegs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30192] = { id = 30192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Town, It's on Fire", description = "I don't know if you noticed, but my town is burning...\n\nThe sprites have started kicking the braziers! They're going to set fire to the whole town!\n\nPlease help us! Stamp out any fires you see!", completion = "I really wish you guys would stop throwing the buckets at the fire too� just the water would have been fine.\n\nReally though, it's a relief that you're here to help. Thank you.", objectives = "Put out 30 Brazier Fires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30193] = { id = 30193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meating Expectations", description = "Hard workers deserve hearty meals, but I'm all out of good meat!\n\nCan you head out into the forest and get me some fresh gazelle meat?", progress = "No shortage of mouths to feed, that's for sure!", completion = "Doesn't get much fresher! Thank you, {class}.", objectives = "Retrieve 10 slabs of Fairlands Gazelle Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30194] = { id = 30194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Storm", description = "The villagers have lost another yak this morning to one of the thundermaw wolves from across the river. The wolves grow bold.\n\nThis is a sign that they are breeding beyond the vale's ability to sustain them. It's time to thin their numbers again.\n\nIf you are willing to aid me in this, you would have my sincere appreciation.", completion = "Your act is one of a responsible hunter. I respect you for it.", objectives = "Kill 8 Thundermaw Wolves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30195] = { id = 30195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blooming Blossoms", description = "Would you do a humble merchant a favor? I've been needin' to refresh my stock of eternal blossoms. They grow in the woods nearby.\n\nCould you help me out, perhaps?", progress = "Was your flower-gathering bountiful?", completion = "Aha! You are quite the kind patron.\n\nThank you... thank you.", objectives = "Collect 10 Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30196] = { id = 30196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lushroom Rush", description = "Building a new village makes for hungry workers it seems!\n\nI have a hearty stew recipe prepared, but I need some lushrooms from the Tu Shen Burial Ground to the east. Apparently there are roused spirits causing trouble up there though, and I'm not very well suited for the violent life.\n\nIf you're heading up the burial grounds today, could you collect some lushrooms for me?", progress = "I can hear the hungry bellies rumbling throughout the village!", completion = "Good timing! The stew's almost ready.\n\nYou have my thanks.", objectives = "Collect 12 Lushrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30197] = { id = 30197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cart Ride", description = "The vale has been quiet all morning. I'm sending Rook with a cart of supplies out to the XXX Village. You should join him.", sourceObjective = "Ride a delivery cart to XXX Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[30200] = { id = 30200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Ashen Webs", description = "We used to have the trainees clear out the ruins of spiders as part of their training, but now we send them straight to the mogu front. The spiders have gotten out of control.\n\nCare to put things back in control?", completion = "You're quicker than the trainees, but I would have been disappointed if you weren't. Thanks.", objectives = "Kill 8 Ashweb Spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30204] = { id = 30204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Not a Rock!", description = "Okay, these spiders are seriously creeping me out. Especially those egg sacs they leave lying around that I keep accidentally stepping on only to be covered in very little but very creepy spiderlings. Ug, makes me shudder just thinking about it.\n\nI say you burn them. Burn them all.", completion = "Thank you. I'd say I have about a week of Anji making fun of me for the screaming, and then I should be in the clear.", objectives = "Kill 50 Ashweb Spiderlings. Use Kun's torch to burn them inside their pods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30205] = { id = 30205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runelocked", description = "Hello, friend.\n\nOne of Leven's men brought word to me of a mogu artifact in the eastern ruins, but said he couldn't figure out how to retrieve it. I suspect it's guarded by one of their rune locks.\n\nIf you go to the artifact, you should find four runes somewhere nearby that when activated will release the lock. If you could bring the artifact back to me, I would be very grateful.", progress = "Did you find the runes I was telling you about?", completion = "This is marvelous... very well perserved. Thank you very much, friend! I owe you for this.", objectives = "Retrieve the Ancient Mogu Artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30206] = { id = 30206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runes in the Ruins", description = "In the walls of the ruins themselves, there are precious runestones that we can make use of back in the eastern vale.\n\nIf you see any while you are within the ruins, would you be so kind as to bring them back to me?", progress = "These runestones were used as sources of power long ago, when the mogu still ruled the vale.", completion = "These are lovely! Thank you, kind {class}.", objectives = "Collect 12 Guo-Lai Runestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30207] = { id = 30207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: 1st Place" }
quests[30208] = { id = 30208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: 2nd Place" }
quests[30209] = { id = 30209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: 3rd Place" }
quests[30210] = { id = 30210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: 4th Place" }
quests[30211] = { id = 30211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: 5th Place" }
quests[30212] = { id = 30212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: 6th Place" }
quests[30225] = { id = 30225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashweb Matriarch", description = "My dear Kun spotted more spiders pouring out of the Guo-Lai Halls this morning, and when he went to investigate, he uncovered another spider matriarch inside.\n\nI need you to kill it.", completion = "You've got a follow-through I can respect, {class}. Thanks.", objectives = "Kill Bloodtip, the Ashweb Matriarch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30226] = { id = 30226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood on the Rise", description = "A small group of mogu have been sighted on Ruin's Rise, to the north.\n\nExtinguish them.", completion = "As it should be. Thank you.", objectives = "Kill 8 Shao-Tien mogu on Ruin's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30227] = { id = 30227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wulon, the Granite Sentinel", description = "One of the quilen statues in Guo-Lai Halls came to life and nearly killed my precious Kun. I won't have it! No one threatens my Kun.\n\nI want you to go in there and smash the thing to pieces. I'd do it myself, but I need to attend to my lover's wounds first.", completion = "Thanks. I owe you one, {class}.", objectives = "Kill Wulon, the Granite Sentinel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30228] = { id = 30228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troubling the Troublemakers", description = "The wood sprites are back. I need you to kill them before they cause anymore trouble.", completion = "Some peace and quiet. Thank you.", objectives = "Kill 8 Stonebark sprites.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30229] = { id = 30229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greater Danger", description = "I apologize for my harsh words earlier. Dezco might have been right to wait and move west with a unified strength.\n\nThe mogu hit us hard when we were searching the ruins west of here. They ambushed us using summoning portals and some dark magics. I haven't seen such evil sorcery used since Outland. \n\nWe need a respite. Head west, kill their summoners, cut their supply line.", progress = "Did you break their reinforcements?", completion = "With their reinforcements severed we can begin to mount an offensive against their Lord Reclaimer.", objectives = "Kill 8 Korjani Reclaimers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30230] = { id = 30230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Reclaim", progress = "Every artifact in our possession is one less weapon in mogu hands.", completion = "Well done {name}. You have removed the sword from the child's hands.", objectives = "Recover 10 Mogu Artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30231] = { id = 30231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pomfruit Pickup", description = "I need more pomfruit! Go knock some loose from the trees for me, would you?\n\nTake this, I use it when I go harvesting. Things go quicker when the fruit comes to you!", progress = "I always misjudge how much juice I can get out of these things.", completion = "Delicious! I am indebted to you, my friend.", objectives = "Gather 12 Pomfruit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30232] = { id = 30232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruffling Some Feathers", description = "The hawk numbers in the vale are thriving. This is opportune for our fletchers, for we will need a great number of feathers if we are to keep the archers upon the wall stocked with arrows.\n\nIf you would not mind, could you aid us in gathering these feathers?", progress = "I hesitate to continually ask such menial things of one so accomplished as you, but we are in desperate times.", completion = "You have my most gracious thanks, young one.", objectives = "Gather 80 Silken Feathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30233] = { id = 30233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracklefang", description = "Hi! So, I have a dilemma. I've only got one good wolf name.... wait for it... Cracklefang! I know, amazing right?! But now there are TWO big nasty wolves in the forest, which is all kinds of confusing.\n\nI need you to kill one of them so I can free up the name. Should be simple enough, yeah? Especially for someone of your incredibleness.\n\nSo, are you on board? I'm hoping for yes!", completion = "Yes! Only one Cracklefang remains to terrorize the goats and yaks of the Vale of Eternal Blossoms. As it should be! Thank you for that!\n\nI sure hope no more big nasty wolves turn up. I really don't think I'm going to be able to come up with another name that can live up to that one.", objectives = "Kill Cracklefang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30234] = { id = 30234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vicejaw", description = "Vicejaw! Sounds absolutely violent, does it not? I came up with it myself, and I think it's very suiting. I tried to wrestle my staff away from him for hours, but he simply would not let go!\n\nOkay, it was really more like a few seconds. I like to be truthful to my friends, even if it makes my stories significantly more boring.\n\nAnyway, would you be so kind as to release your oh-so-potent wrath upon this crocolisk with a vice-like jaw, and then kindly bring my staff back? Preferably in-tact!", completion = "My staff! My gorgeous staff! We shall never part again. I shall lean on you, and you will always be there. And I promise not to poke crocodiles with you anymore.\n\nThank you, friend. Your staff retrieval skills have proved invaluable today!", objectives = "Kill Vicejaw and return Ren's Longstaff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30235] = { id = 30235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quid Pro Quo", description = "Quid is a very powerful and very ancient water spirit, though you might not know it with his child-like ways.\n\nThis morning, Quid nearly killed several villagers in the bar when he jokingly caused several of the water kegs to explode.\n\nAs long as the water flows, Quid will remain. He cannot be slain. But he can be reminded that we do not take his dangerous antics in jest.\n\nWould you be willing to carry this message to him on behalf of the village?", completion = "For the sake of the villagers, I hope he remains at bay for some time.\n\nThank you, my friend.", objectives = "Defeat Quid, the Spirit of the Misty Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30236] = { id = 30236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aetha", description = "It seems Aetha has been levitating the livestock and dropping them into the river again. The mayor has requested that we remind her that these kinds of jokes are not welcomed.\n\nWould you be so generous as to travel to the ridge above the village and teach her this lesson? You cannot kill her, you can only send her away for a time, but this should prove a potent reminder.", completion = "The spirits may be childlike, but they possess generous mounts of strength for their size. Your victory is no small thing, and is very appreciated.", objectives = "Defeat Aetha, the Spirit of the Golden Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30237] = { id = 30237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pandaren Uprising Relived", description = "In the Tu Shen Burial Ground to the east, the spirits of ancient mogu are locked in battle with the spirits of our pandaren ancestors that rose up against them. The spirits have seen no rest since the return of the mogu to the valley.\n\nIf you would be willing to go to the graveyard and force the mogu to relive their defeat again, we might offer some lasting peace to the spirits of our ancestors.", completion = "The spirits of the pandaren monks seem invigorated by the deaths of their mogu oppressors.  It is a small victory, but it shows respect to great heroes of the past.", objectives = "Kill 8 Ancient Mogu Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30238] = { id = 30238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Rest", description = "The spirits of our ancestors are reliving one of the most revered battles in our history at the Tu Shen Burial Grounds to the east.\n\nDo as I ask, {race}, and honor their gravestones. Remind them that they are respected even these many years later, and that they are deserving of peaceful rest.", completion = "Thank you, my friend. You respect for our ancestors means a great deal.", objectives = "Honor 6 Pandaren Gravestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30239] = { id = 30239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lao-Fe the Slavebinder", description = "You can hear the spirit of Lao-Fe, the Slavebinder shouting taunts from the cave at the top of Tu Shen Burial Mound.\n\nDefeating him will surely serve to ensure victory for the spirits of the pandaren monks.", completion = "Lao-Fe the Slavebinder was one of the most spiteful and vicious mogu of his time. May defeating his spirit act as a reminder to all the mogu in the vale of the fate that awaits them if they seek to defile the sacred pools again.\n\nYour strength is unquestionable. You have my respect, {class}.", objectives = "Kill the Spirit of Lao-Fe, the Slavebinder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30240] = { id = 30240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival Ring: Flame", description = "This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare.\n\nSurvive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.", progress = "The constant danger in the ring prepares us for life or death fighting we have to endure outside the wall.", completion = "Not bad, {class}. Not bad at all.", objectives = "Enter the Survival Ring and survive for 60 seconds without leaving.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30241] = { id = 30241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Stoneplow", description = "So much death. And more to come, if Ambassador Han's stories of the mantid are to be believed.\n\nWe must help. We must do our part to save lives.\n\nTravel to Stoneplow. Warn them of the coming mantid attack.\n\nI will join you with what forces I can muster once I have laid Kor's body to rest.", completion = "Mantid from the south? This is not a good day.", objectives = "Travel to Stoneplow Village in Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30242] = { id = 30242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival Ring: Blades", description = "This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare.\n\nSurvive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.", progress = "The constant danger in the ring prepares us for life or death fighting we have to endure outside the wall.", completion = "Not bad, {class}. Not bad at all.", objectives = "Enter the Survival Ring and survive for 60 seconds without leaving.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30243] = { id = 30243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantid Under Fire", description = "The mantid are attacking again, and we're a bit short-handed up on the wall. In hopes that you'd help, I saved one of the more fun posts for you: the hot oil!\n\nIt's a bit more violent and a bit less scandalous than it sounds.\n\nIt's simple really. Get up on the wall, find one of the oil stations, and dump it on any of the mantid pouring up against the wall. It's very effective.", progress = "The hard part is the cleanup. Fortunately, you're not responsible for that.", completion = "You've done devastating damage to the mantid forces. The wall defenders should be able to get things under control.", objectives = "Use a Hot Oil Cauldron to kill 80 mantid near the Gate of the Setting Sun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30244] = { id = 30244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Along the Serpent's Spine", description = "There are mantid on top of the wall. The defenders on the ramparts are calling for help!", completion = "The mantid forces on the wall have been thinned.", objectives = "Kill 10 Krik'thik mantid on the Gate of the Setting Sun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30245] = { id = 30245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Scouts", description = "We sent some scouts towards the Five Sisters to the north to try and find whatever mogu leader has risen up to direct their movements in the valley. Few have returned.\n\nI'd like to think they're just off downing too much ale or being irresponsible with some young pandaren, but they may actually be in some trouble.\n\nCan you scout for the scouts? And see if they've turned up any information on that leader while you're at it?", completion = "The scout reports have pinpointed the mogu leader's position.", objectives = "Recover 3 Shado-Pan Scout reports.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30246] = { id = 30246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upon the Ramparts", description = "Some of the mantid have made it on top of the wall. There's some risk they'll route the soldiers we have posted there if their numbers are large enough.\n\nI need you to get on top of the wall and help clear out any that have broken through.", completion = "The mantid forces on the wall have been thinned.", objectives = "Kill 10 Krik'thik mantid on top of the Gate of the Setting Sun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30247] = { id = 30247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roll Club: Vale of Eternal Blossoms", description = "Follow the flags. Make the checkpoints. Round the loop. Get back to me before your time is up.\n\nSpeak to me when you're ready to roll.", objectives = "Complete the Vale of Eternal Blossoms roll course.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30248] = { id = 30248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Butcher", description = "Scouts reports place the displaced Shao-Tien Imperion at the north end of the wall.\n\nAngi Autumnlight spelled out your goal in no uncertain terms: find this leader and kill him.", completion = "Look at you! All proactive and assertive. Looks good on you.", objectives = "Kill Bai-Jin the Butcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30249] = { id = 30249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Setting Sun", description = "A giant beast has burrowed under the gate into the courtyard. The defenders need your help!", completion = "I heard you performed some heroics in the courtyard! Your name will be remembered on the wall for some time. Well done, {name}.", objectives = "Kill Kri'chon, the Corpse-Reaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30250] = { id = 30250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival Ring: Thunder", description = "This is one of the challenges I put upon my warriors during peaceful times to keep them strong and fast. Let's see how you fare.\n\nSurvive the ring for 90 seconds without getting pushed out or killed. Stay on your toes.", objectives = "Enter the Survival Ring and survive for 90 seconds without leaving.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30251] = { id = 30251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyraxxis, the Krik'thik Swarm-Lord", description = "A giant mantid is terrorizing the inside of the wall. It seems doubtful that the defenders will be able deal with it without you.", completion = "I like your initiative. Good work.", objectives = "Kill Vyraxxis, the Krik'thik Swarm-Lord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30252] = { id = 30252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Helping Hand", description = "I've been pushing and shoving and hammering all morning, but it's hopeless.\n\nThese rocks won't budge!\n\n\"It will be a breeze,\" Grandpa said. \"Farming's like breathing!\" he said. Maybe for him, but not for me!\n\nHow am I supposed to succeed at this whole FARMING thing if I can't even clear my farm for planting?\n\nHey, wait a minute. You look like you've got some muscle on you.\n\nWould you be willing to help me out? Just until I can catch my breath.", progress = "I really wasn't cut out for this type of work. I didn't exactly grow up in the country.", completion = "What? You cleared the rocks? That's great news!\n\nMaybe now I can actually start growing something on this farm!", objectives = "Destroy 8 Unbudging Rocks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30253] = { id = 30253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Family Farm", description = "D-did you hear what they said?\n\nIt's almost like they don't want me here. Like...I'm not good enough.\n\nSure I've never run a farm before, but I know how to plant a seed and how to pick a turnip.\n\n<Farmer Yoon's eyes light up.>\n\nYou know what? I'm going to show them that I can also become a master farmer!\n\nI'm going to turn this farm into one of the most prosperous in the Valley!\n\nIt's too much work for one pandaren, though. Come on! Will you help me?", objectives = "Join Farmer Yoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30254] = { id = 30254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow II: Tilling and Planting", description = "Okay, now we've got our seeds, it's time to plant them.\n\nFirst, we have to prepare the soil! You gotta till the soil and break it up to make a nice bed for our little sprouts.\n\nTill those two plots of soil over there, then plant the seeds in them.", completion = "Nicely done.\n\nNotice how those seeds sprouted immediately? That's part of what makes this valley so ideal for farming - something about the soil here just makes veggies grow like crazy!\n\nThe work's not done yet, though.", objectives = "Till 2 plots of Untilled Soil to create Tilled Soil. Then, use the EZ-Gro Green Cabbage Seeds on 2 plots of Tilled Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30255] = { id = 30255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow III: Tending Crops", description = "My grandfather used to say \"Yoonie, a cabbage is like a woman: ignore her and she'll turn rotten. Pamper her and she'll grow big and plump and you can put a ribbon on her and take her to market to show her off to your frie-\" look, he was from a different time, okay?\n\nThe point is, now that our cabbages have sprouted, they need attention! Today they look a little dry, so you should water them.\n\nHere's the old watering can grandpa left. It will always be near the field if you need it.", progress = "Come to think of it, grandpa said a lot of really offensive things.\n\nMaybe I should avoid quoting him from now on...", completion = "Great, the cabbages are tended and looking good!\n\nToday they were thirsty, but you never know what they might need. Pay close attention to your crops and tend them accordingly.\n\nI got all kinds of advice from my grandpa, so if you're ever unsure of how to take care of something, feel free to ask!\n\nJust make sure it's strictly related to farming...", objectives = "Use the Rusty Watering Can to water 2 Parched EZ-Gro Green Cabbages at Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30256] = { id = 30256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow IV: Harvesting", description = "It's time for our hard work to pay off! Normally we'd have to wait a day before the crops are ready to harvest.\n\nFortunately, those seeds Greenfield gave us were specially designed to grow FAST. The yield won't be worth much, but they're good for stepping new farmers through the process.\n\nOur cabbages should be ready to harvest. I'll let you do the honors, of course!", progress = "Look at those... err, what do they say around here? Oh yeah, b'yoots!\n\nLook at those b'yoots!\n\nI think I'm getting the hang of this farmer thing.", completion = "Well, those are the basics!\n\nTill the soil, plant the seeds, tend to any threats, then wait for the results!\n\nToday was easy, but stay on your toes: my grandfather told me all kinds of crazy stories about farming at Sunsong Ranch.\n\nFarming ain't all giant turnips and roses, you know.", objectives = "Harvest 2 EZ-Gro Green Cabbages from your field and bring them to Farmer Yoon in Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30257] = { id = 30257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow V: Halfhill Market", description = "All right friend, all of that farming was just for practice!\n\nAre you ready to try the real thing?\n\nThere's a lady by the name of Gina Mudclaw who runs the Halfhill Market, which is across the street to the south.\n\nI heard she's looking to buy some vegetables. Since it's your first time meeting her, you shouldn't go empty-handed.\n\nWhy don't you look around the ranch and see if there are any items hiding around?\n\nMight be that we'll find a good gift to take to our new neighbor!", progress = "Hey, haven't seen your face around here before! What's your name?", completion = "Oh my, a marsh lily!\n\nHow did you know that these are my favorite? I just might take a liking to you, stranger.\n\nThank you!", objectives = "Investigate the Dark Soil underneath Farmer Yoon's house, then give a gift to Gina Mudclaw at the Halfhill Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30258] = { id = 30258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mung-Mung's Vote I: A Hozen's Problem", description = "I've been thinkin' about how to get into the Tiller's good graces, {name}.\n\nNow, the Tiller's Union accepts new farmers each year, and there are five members on the voting council.\n\nWe already got Gina's vote, but we'll have to prove ourselves to the other four members of their board.\n\nWhy don't you go over and say hello to Mung-Mung? He works with Mr. Mudclaw out on the Mudclaw's farm to the northwest.", completion = "Yes?", objectives = "Speak to Mung-Mung at Haohan Mudclaw's House in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30259] = { id = 30259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mung-Mung's Vote II: Rotten to the Core", description = "Dem virmen's back!\n\nThey been biting Mr. Mudclaw's carrots. Ruining his crop. And who is gonna pay? Mung-Mung, that's who!\n\nYou go get the chewed up carrots before Mr. Mudclaw sees. They all over the fields to the southwest, and down under the ground in the virmen's tunnels, too.\n\nOtherwise, Mung-Mung in big trouble.\n\nYou do this for me?", progress = "I don't see no chewed up carrots. You don't see no chewed up carrots. Mr. Mudclaw never know, okay?", completion = "What do you mean, no virmen chewed them up? Teeth marks too small? WHAT? Then who else do this?", objectives = "Collect 10 Partially Chewed Carrots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30260] = { id = 30260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing the Farm I: The Weeds", description = "Hey {name}, I've been thinkin' recently about expanding my farm.\n\nSee that plot there that's just covered in weeds? If we can get rid of those weeds, we could use that land for planting.\n\nI heard there's a farmer by the name of Gai Lan who knows a thing or two about weed whackin'.\n\nHis farm is just out west. Go talk to him and see if he'd be willing to help us.", completion = "Oh yeah, Farmer Yoon. I've seen him around town.\n\nSeems like a nice enough fella.", objectives = "Speak to Gai Lan at The Heartland in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30261] = { id = 30261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roll Club: Serpent's Spine", description = "Get to the bottom of the wall in the fastest time possible.\n\nSpeak to me when you're ready to roll.", progress = "Ready to roll?", completion = "When they built the wall, I don't think they knew we'd be using it for this.", objectives = "Complete the Serpent's Spine roll course.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30263] = { id = 30263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing in the Forest", description = "The Shao-Tien are on their heels. Most of them retreated to Winterbough Glade after their last defeat. We should press the advantage.\n\nTake the fight to these mogu in the clearing to the northwest. Let us leave them no minute of rest as long as they remain in the Vale.", completion = "We must seize our advantage when an opportunity presents itself. We must make the Shao-Tien pay for every moment they remain in the Vale.\n\nYou've done well this day, {class}.", objectives = "Kill 6 Shao-Tien mogu in Winterbough Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30264] = { id = 30264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy at the Gates", description = "The mantid forces are pouring against the wall. I've arranged for some flying serpents to cut away at their forces from the air.\n\nWould you be willing to take the reigns on one of them?", completion = "Kun tells me you were amazing out there. You impress my man, you impress me.\n\nGood work.", objectives = "Use a Shado-Pan Sky Serpent to kill 60 Krik'thik attackers, 3 Krik'thik War Wagons, and 3 Krik'thik Catapults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30265] = { id = 30265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparkle in the Eye", description = "I've been staring down into the waters of the lake, pondering life, love, and everything beautiful, and suddenly I realized that the sparkles in the water aren't just a reflection of my radiant personality, there are actually some sort of shining objects down there! Surely valuable.\n\nWould you mind taking a drip and relieving the lake's depths of its mysterious sparkles? Pretty please?", progress = "What were these mysterious sparkles? I've been dying with curiosity. Coins? Goblets? A dozen discarded wedding rings?", completion = "Rubies! Valuable, yes! Suggestive of an interesting backstory involving a dozen broken-hearted brides? Likely not. Still, quite the find!\n\nThank you my marvelously benevolent friend! You have saved me some awkwardly wet robes with your generous aquatic ways.", objectives = "Recover 8 Shining Rubies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30266] = { id = 30266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodied Skies", description = "We have cannons set up on the top of the towers flanking the main gate. They are our best method to clear the skies when the flying mantid try to pass over the wall, like they are now.\n\nLooks like you're on, {name}.", completion = "You've got good aim, {class}. I'll remember that the next time the fliers come.", objectives = "Kill 30 Krik'thik Swarmers using a Setting Sun Turret.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30267] = { id = 30267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watery Woes", description = "I love fishing. I'd be enjoying myself much more, however, if I had my bait and my lures. They were thrown away in a... a misunderstanding with my wife, Rin.\n\n<Gladecaster Lang sighs.>\n\nShould I let a whole day of fishing be ruined, just because of a little domestic squabble? No! All I need is bugs and feathers, after all, and this glade is filled with those two things.\n\nCare to help a fisherman out?", progress = "I refuse to not fish. Fishing's who I am!", completion = "Finally, someone who understands me. Fishing is what it's all about, right?\n\nMaybe I should leave New Cifera... just pack up my things and join the Anglers, down in the south. Of course, I couldn't leave my family behind...\n\nBut still... a pandaren can dream, right?", objectives = "Obtain 18 Glade Glimmers and 5 Spindly Bloodfeathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30268] = { id = 30268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Murksweats", description = "Take a good look. The river nearby is swarming with these snakes. Their venom causes a condition the locals call \"the murksweats.\"\n\nSeveral refugees were bitten as they fled the temple and have already begun to show symptoms: nausea, vomiting, and intense sweating as the body rejects all fluids, causing dehydration and potentially death.\n\nWe are administering anti-venom as quickly as possible, but we'll need more venom glands. Don't bother removing the glands yourself - just bring back the whole head.", progress = "<Anduin is focused intently on his hands, swiftly carving venom glands from the snakes.>\n\nInside the jaw... two inches behind the second set of fangs...", completion = "Thank you, {class}. I knew you'd be hardy enough to handle it.\n\nJudging by the sounds coming out of these refugees, I would not wish the murksweats on my worst enemy.", objectives = "Gather 6 Murkscale Heads from Murkscale Strikers in Krasarang River.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30269] = { id = 30269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsafe Passage", description = "As we say at the temple: \"Never fight a tiger with a hozen on your back.\"\n\nWe will deal with the sha, but first we must see to the more immediate... nuisance.\n\n<Koro slams the writhing saurok HARD against the stone.>\n\nGroups of refugees from the temple are heading for a camp to the north, but they're being ambushed by saurok. Help me see the next group to the camp and we'll figure out our next move from there.", completion = "Thank you, {name}. We would not have made it without your help.", objectives = "Help Koro Mistwalker escort a group of refugees from the Temple of the Red Crane to Crane Wing Refuge. Speak with Koro first to begin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30270] = { id = 30270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinding the Riverblades", description = "\"A hooded falcon catches no quarry.\"\n\nThis is one of the first mantras we teach young monks at the temple. It means that even a foe as swift and lethal as a falcon can be neutralized by depriving its senses.\n\nThe saurok have scouts all over the region acting as eyes for their raiding parties.\n\nIt's time we put their eyes out, don't you think?", completion = "Well done. I only wish I could have accompanied you...\n\nThe blood on these hand-wraps is not my own, you know.", objectives = "Kill 8 Riverblade Pathstalkers in the areas surrounding Crane Wing Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30271] = { id = 30271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sha Can Awe", progress = "Look for Crane Wing pandaren who are falling to despair and slay sha near them while I support you!", completion = "Honestly, I'm a little surprised that worked.\n\nPandaria is proving to be a land where the lines between metaphor and reality are blurred.", objectives = "Kill sha near 10 Hopeless Monks or Acolytes to inspire them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30272] = { id = 30272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking the Rain", description = "Now as for that \"striking the rain\" part... well, sometimes you have to.\n\n\"Hope is the sun behind a stormy sky - ever in the heart, but veiled to the eye.\"\n\nThere seems to be no end to the sha pouring out of the temple. But in order to see beyond the veil of despair, you must carve through it.\n\nWith any luck, you'll find a sun behind the clouds...", progress = "We shouldn't press further into the temple before clearing out some of the sha presence outside.", completion = "You know something, {name}? We make a pretty good team!", objectives = "Kill 18 Haunts of Despair at the Temple of the Red Crane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30273] = { id = 30273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the House of the Red Crane", completion = "You have vanquished the Sha of Despair. My order can handle the remaining cleanup from here.\n\nIt seems the time has finally come to face the consequences of Shaohao's actions.\n\nThis conflict has been a long time coming - the arrival of your people was merely a catalyst. Now, your help will be necessary if Pandaria is to survive.", objectives = "Enter the basement of the Temple of the Red Crane and defeat the Sha of Despair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30274] = { id = 30274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcanic Oubliette", description = "An Alliance member? Here? Elune be praised.\n\nMy team has encountered a snag. We opened a portal to this land using some ancient scrolls we had found that predated Azshara's rule.\n\nUnfortunately, the coordinates provided on the tablets were warded and the portal that meant to take us to our destination landed us in this oubliette.\n\nWe have been trapped here for days, and it is slowly leaching our energies to power itself.\n\nCan you find the nearby shackles that bind the oubliette and disable them?", completion = "Fabulous! Your timing was impeccable. Another day in there and I think we would have wasted away to nothing.\n\nNow we can continue our search for the Pools of Youth!", objectives = "Find and disable the 3 Oubliette Shackles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30275] = { id = 30275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crocolisk Tale", description = "How could this crocolisk have grown so large?\n\nCertainly, rumors exist of very old crocolisks that have grown to enormous sizes... but this female can't be more than a dozen years old.\n\nPerhaps someone in New Cifera can shed some light on the subject.", progress = "What's that you've got there?", completion = "This tail came from a crocolisk? Funny, we don't get many crocs this far upstream.\n\nHave you seen some of the enormous fruits and vegetables that our farmers can grow? Your crocolisk grew so large for the same reason - there's something in the water.\n\nWhat it is, we're not quite sure... but we count it among our blessings. Humongous vegetables are great. The odd giant crocolisk every now and again is really just a side effect.", objectives = "Bring the Enormous Crocolisk Tail to Yan at New Cifera in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30277] = { id = 30277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crumbling Hall", description = "An ancient mogu artifact has been uncovered in the Guo-Lai Vault, beyond the Hall of Statues. We've made repeated attempts to retrieve it, but none have been successful.\n\nWe cannot let this artifact fall into the hands of the Shao-Tien. I need someone capable to retrieve it, and quickly.\n\nAre you in?", progress = "Have you recovered the artifact yet?", completion = "When everyone else lets me down, you follow through. That's why I like you.\n\nThank you, {name}.", objectives = "Retrieve the Ancient Guo-Lai Artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30278] = { id = 30278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE FOR PROGRESSION" }
quests[30279] = { id = 30279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE FOR PROGRESSION" }
quests[30280] = { id = 30280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunder Below", description = "Roars have been echoing out from inside the Guo-Lai Halls. The mogu have awakened some ancient beast, and it will not be long before they attempt to release it upon my men.\n\nFind your way to the Hall of the Serpent and slay the beast before it can be unleashed upon us. I would trust no other with such a dangerous and important task.", progress = "Have you slain the beast?", completion = "You accomplish what I doubt I could even overcome myself. I am humbled by your valor.", objectives = "Slay Milau.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30281] = { id = 30281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silent Approach", description = "<He leans over and draws a picture of what can only be a mogu, points towards the lake to the west, drags the blunt side of his dagger across his throat, and looks at you expectantly. It seems he wants you to kill mogu at Whitepetal Lake.>", completion = "The mogu numbers seem to be sufficiently thinned.", objectives = "Kill 6 Shao-Tien mogu at Whitepetal Lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30282] = { id = 30282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Away the Filth", description = "The mogu have erected their filthy banners around the lake to the west, claiming it as their own. Take this torch and show them what we think of their banners.", completion = "I'll take the smoke on the horizon to mean that they've received our message. Good.", objectives = "Burn 10 Shao-Tien Banners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30283] = { id = 30283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Smashing Impression", description = "Sometimes I feel sorry for these mogu... maybe ripping out the spirits of other races is just their way of coping with family issues at home? Maybe we should be more sympathetic to where all this aggression stems from?\n\nOr we could just smash all their soul-stealing ritual objects down at the lake. That sounds more fun to me personally.", completion = "If they come asking who rudely crushed all their little statuettes, I'll tell them it was you.\n\nNot that I don't appreciate your help. You're lovely.", objectives = "Destroy the Shao-Tien Ritual Statues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30284] = { id = 30284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thousand Pointy Teeth", description = "The water has been frothing with danger this day! Some sort of swarming, meat-eating fishy nastiness has taken up residence in our lake! Deplorable. And just when I was considering stripping down to my nothings to take a mid-day dip!\n\nYou are adept in the ways of slaughtering any manner of nasty, are you not? Would you put your skills to use this day, in the name of pandaren everywhere desiring a swim?\n\nIt's a truly noble cause, especially with me among their ranks!", completion = "Aren't you just the sweetest thing?! I do rather like you.\n\nI'm going to take that afore-mentioned dip now. I'll be modest and delay my disrobing until you depart, as a repayment for your kindness.\n\n...you're missing quite the sight though, I must say.", objectives = "Kill 9 Knifetooth Swarmers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30285] = { id = 30285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wu Kao Scouting Reports", description = "There were some scouting reports unaccounted for after the attack. If we're lucky, they're still out in the village, but the mogu may have gotten their hands on some of them as well.\n\nIf you could bring back any scouting reports you find, it would definitely put my mind at ease. We can't afford to let the mogu in on our positions or any of the artifacts we've found, lest the men be in even more danger than they already are.", progress = "Any luck finding those reports?  I'm worried for the safety of our men in the field if too much information falls into mogu hands.", completion = "You are very kind, {name}. Thank you for putting my mind at ease.", objectives = "Recover 3 Wu Kao Scouting Reports.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30286] = { id = 30286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backed Into a Corner", description = "Many villagers are cornered and scared, unable to defend themselves. You will need to defend them. Rescue them.\n\nGo quickly friend, save as many as you can!", completion = "We've holed up everyone we can in the bar. We should be able to protect them for now.\n\nThank you again for your help, {name}. You always seem to be there right when we need you.", objectives = "Rescue 6 Cornered Mistfall Villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30287] = { id = 30287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Make Poor House Guests", description = "Leven sent Rook here to stop mogu, but there are more than Rook can kill alone.\n\nYou help?  Rook will tell Leven you helped.  Promise.", completion = "Rook can handle rest of mogu.  Thanks for help.  Good man.", objectives = "Kill 6 Shado-Tien attackers in Mistfall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30288] = { id = 30288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Town, It's On Fire Again", description = "I don't know if you noticed, but my town is on fire... again.\n\nWe have water buckets all over town, but no one can get out to put out the fires. Please, please, help us!", completion = "We owe you so much... thank you, {class}.", objectives = "Use Mistfall Water Buckets to douse 60 fires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30289] = { id = 30289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freeing Mind and Body", description = "Mogu stealing peoples minds! Making them do evil things.\n\nDon't kill them, just kill the mogu, then they forget about all the mogu mind stealing and stop being evil. You should fix people like Rook is.", completion = "Lots of villagers inside and safe now. You do good work.", objectives = "Free 6 Dominated Guards by killing their controllers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30290] = { id = 30290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonebound Killers", description = "Mogu stone dog creatures chasing villagers and hurting them. Rook try to smash some, but they too fast.\n\nYou help smash some too?", completion = "Yes! You faster than rook. Do good!\n\nThank you, friend.", objectives = "Kill 8 Stonebound Quilen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30291] = { id = 30291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stunning Display", description = "I've been talking to Tantan here... again... and he insists that fishing is some kind of fabulous. I was skeptical, but I gave it another go. I'm not a big fan of that whole holding a stick and waiting method though, so I tried something a bit more direct.\n\nWould you be a doll and go collect any of the still intact fish floating belly up in the lake for me?", progress = "As an added bonus, my method ensures they're already cooked! If that's not a marvel of modern efficiency, I don't know what is.", completion = "Marvelous! You're quite the efficient fetcher.\n\nI'm grateful that you don't mind getting that fancy armor of yours wet.", objectives = "Collect 12 Stunned Whitepetal Carp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30292] = { id = 30292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rude Awakenings", description = "The mogu are taking over the minds of the saurok at the lake to our west and turning them against us! The thing is, they were already against us, so I'm not sure they really thought this thing through fully.\n\nAnyway, Anji's the fighter in this pair, I'm more the lover, so I'm looking for someone to do all the weapon swinging and spell flinging and war crying and such.\n\nCan you go kill some saurok for me?", completion = "You smell of saurok and mogu. Not a terribly pleasant mix, my friend. But it suggests to me that your task is done, and for that I thank you.\n\nMay we meet again soon under better-smelling terms.", objectives = "Kill 8 Dominated Paleblade Flesheaters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30293] = { id = 30293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Enemy Hands", description = "The Shao-Tien Mindbenders have taken over the minds of our defenders down at Whitepetal Lake to the west. Get down there and kill the mogu that are controlling them, but don't kill the defenders! Killing their captors should free them from their mind control.\n\nSooner would be better. Anji might try to go down there to help soon, and her ability to restrain herself when in the heat of things is not one of the qualities I married her for.", completion = "More than one pandaren is thankful for your help today, that's for sure.", objectives = "Beat 8 Possessed Whitepetal Defenders until they're freed of mogu possession.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30294] = { id = 30294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Comforts", description = "The mindbenders at Whitepetal Lake are pulling the spirits from the corpses of the dead to inflict who-knows-what kind of torments upon them.\n\nI've written on this scroll a rite that will release their spirits from their bodies and send them on their way. Where they go and what happens to them from there I don't know, but it will at least free them from the cruel hands of the mogu.\n\nRead this rite over any of the fallen you find. We'll recover their bodies later.", sourceObjective = "Read the Rite of Release at the bodies of 6 Fallen Golden Lotus Defenders.", sourceObjectiveStatus = "unverified-source-field" }
quests[30295] = { id = 30295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn-in Quest Test Case" }
quests[30296] = { id = 30296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaohun the Soul-Severer", description = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven be happy with us for sure!\n\nYou been good at helping Rook. Want to help more maybe? Please?", completion = "Leader gone. People safe. Rook save village. And friend save village too. Thank you, friend!", objectives = "Kill Gaohun the Soul-Severer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30297] = { id = 30297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baolai the Immolator", description = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven be happy with us for sure!\n\nYou been good at helping Rook. Want to help more maybe? Please?", completion = "Leader gone. People safe. Rook save village. And friend save village too. Thank you, friend!", objectives = "Kill Baolai the Immolator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30298] = { id = 30298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Painting the Ruins Red", description = "The mogu think they can inhabit these ruins uncontested. Let's show them the error in their ways.", completion = "Their foothold in these ruins shall not last the night.", objectives = "Kill 8 mogu in the Ruins of Guo-Lai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30299] = { id = 30299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Stone Unturned", description = "The mogu have forced spirits into their old statues to bring them to life, control them, and turn them against us.\n\nThe only way to free the bound spirits is to destroy their vessels.", completion = "Your efforts here make all the difference. Thank you so much for your help, friend.", objectives = "Destroy 6 Mogu Statues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30300] = { id = 30300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to Success", description = "The mogu have taken prisoners. They'll be tortured or worse.\n\nFind any way you can to free them from their cages.", progress = "I'd rather die than live as a mogu prisoner. They are not kind captors.", completion = "Many of those you saved are back here in camp recovering. You surely have their gratitude, and mine.", objectives = "Find a Shao-Tien Cage Key and free 6 Golden Lotus Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30301] = { id = 30301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offering a Warm Welcome", description = "There is no more sure message we can send them then to burn the tents the sleep in.\n\nScour the ruins. Destroy every tent you find.", completion = "Smoke in the distance tells me that you were successful. Good work, {class}.", objectives = "Burn 6 Mogu Tents in the Ruins of Guo-Lai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30302] = { id = 30302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Imperion Threat", description = "Scouts spotted a Shao-Tien Imperion entering the Guo-Lai Halls. I need someone I can trust to make sure he doesn't come out of there alive.\n\nI think you're the {class} for the job.", completion = "You haven't let me down.  I won't forget that.", objectives = "Kill the Shao-Tien Imperion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30304] = { id = 30304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard as a Rock", description = "Hey! You know what awesome thing happened to me this morning?\n\nI was strolling through the ruins with Anji, eyes on the ground so I wouldn't step on anymore of those creepy spider pods, when one of the statues came to life and tried to smash me!\n\nAnji ended up doing the smashing. But I'm not satisfied. I think that you should go out there and smash all the statues, whether they're moving or not. It's the only way to be sure.", completion = "Your ruins vandalizing efforts are appreciated, friend.", objectives = "Destroy 10 Mogu Statues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30305] = { id = 30305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Knows What He's Doing", description = "You know He Softfoot? Sneaky guy, don't talk much. He put traps all over ruins for mogu. He said Rook just need to trick mogu into traps. Rook don't really know how.\n\nMaybe you do it? You find traps, you get bad guys into traps? Can you not tell He though, please?", completion = "You really good friend. Rook like you. Thank you, good friend!", objectives = "Lure 8 enemies into He's Poison Traps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30306] = { id = 30306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Ring", description = "We have some fresh trainees that are far from being a danger to you, but in numbers, they may prove enough of a challenge. And if not, they could use the lesson in humility.\n\nStep into the battle ring when you're ready. Don't go easy on them.", progress = "Step into the ring. Show them how a real {class} fights.", completion = "Very impressive. It seems they have much learning to do. I'll see to that.", objectives = "Defeat 20 Shado-Pan Trainees in the Battle Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30307] = { id = 30307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Vigil", description = "Good to have you with us, {class}. If you're joining the fight, I need more men out up at the Golden Stair to clear out the mogu setting up base there.\n\nCan I count on you?", completion = "We hold this line. It does not matter how long they come, we hold this line.", objectives = "Kill 8 Shao-Tien mogu on the Golden Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30308] = { id = 30308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Hard Quilen", description = "Leven always says the only good quilen is a dead quilen, and I'm inclined to agree. You here to aid the cause?", completion = "Less of those beasts on the field always cheers my day up a bit. Thanks.", objectives = "Kill 6 Granite Quilen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30309] = { id = 30309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set in Stone", description = "The mogu have been sending their narcissistic stone effigies onto our battlefield today. They're brining them to life up on the Golden Stair.\n\nThe bigger they are, the harder we hit'm. You in?", completion = "There's a satisfying amount of ruble strewn across the field today. A sign of your good work.", objectives = "Destroy 6 Mogu Effigies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30310] = { id = 30310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thundering Skies", description = "The mogu have bent the will of sky serpents and turned them against us.\n\nThe defenders won't fare well against them, but you would. Head northwest towards the Golden Stair and remove them from the sky.", completion = "Quite the battle! I think your feat has boosted morale among the troops a bit.", objectives = "Kill 3 Subjugated Serpents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30311] = { id = 30311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Standards", description = "If I had to pick the most important quality for a battle standard, it would be that it's standing up... and not on fire, but mostly the first one. So needless to say, I'm a bit concerned about our standard situation at the moment.\n\nIf some unknown {class} were to be so kind as to take a walk out on the battlefield to our northwest and stand our standards back up, both myself and my extremely sexy yet somewhat commanding wife would be very grateful.", objectives = "Erect 6 Golden Lotus Standards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30312] = { id = 30312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Given a Second Chance", description = "A foolish contingent attempted to mount an offensive on the Golden Stair through the eastern pass, and were bombarded by cannons. Those that made it back are in bad shape, and there are still wounded out in the field.\n\nHere are some bandages. Use these, or any other healing skills you possess, and help get our wounded defenders back to safety.\n\nPlease hurry, there is little time.", completion = "The men you healed made it back safely.\n\nThank you, kind friend. Truly.", objectives = "Heal 6 Wounded Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30313] = { id = 30313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Moving Mists", description = "<He looks down at the dead fog creature at his feet, looks up at you, then points out into the mists surrounding the lake. It seems he wants you to find and kill more of these fog creatures.>", completion = "<He pats you on the shoulder and nods his thanks.>", objectives = "Kill 8 Fog Walkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30314] = { id = 30314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Displaced Paleblade", description = "<He looks down at the dead saurok at his feet, looks up at you, then points out down the lake shore. It seems he wants you to find and kill more of these saurok.>", completion = "<He smiles at you and nods his thanks.>", objectives = "Kill 8 Paleblade Saurok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30315] = { id = 30315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Normal Quest Test Case", description = "Yes?", objectives = "Give me stuff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30316] = { id = 30316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Longshot", description = "I would not normally ask this of grizzle {class} such as you, but since you are to be on the battlefield below the Golden Stair anyway, would you recover spent arrows for the archers?", objectives = "Recover 12 Spent Shado-Pan Arrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30317] = { id = 30317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water, Water Everywhere", description = "How'd you like to make yourself useful?\n\nThe season's been awful dry lately. I need someone to water the crops out in the Heartland. Here's the thing: I need you to water ALL of the crops.\n\nI keep a few kites with Wing Nga, the flightmaster across the way. Grab one of those kites, then throw water on any areas that look dry and dusty.", progress = "Just come back when you're done. And don't break any of my kites.", completion = "Hmph! I knew you were a good waterer when I first saw you. You've got good watering arms.", objectives = "Speak with Wing Nga to borrow a kite, then throw water onto 35 Dusty Spots in the Heartland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30318] = { id = 30318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing the Chicken", description = "Say, you there! {name}, was it? I've got a problem, and I need someone with better legs than mine to help me solve it.\n\nMy prize-winning chicken has flown the coop! Now she's out in the open, mingling with the other hens, wild birds, and... <gulp> ill-intentioned roosters.\n\nMy farm is west of here, south of the Skyrange. Could you find her, and bring her back to me?", progress = "I swear, she's never done this before.", completion = "You found her! You've got an eye for fowl, kid.\n\nI'll hold onto her for now. Don't worry, I'll make sure she's punished later.", objectives = "Pick up Hillpaw's Chickens until you find his Prize-Winning Chicken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30319] = { id = 30319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Problems", description = "One of my farmhands, Wika-Wika, has been tilling the soil in my westernmost field. I understand he's had some problems with pests.\n\nHe's got plenty of pesticide to spray the bugs that eat my crops, but I'm afraid he has no way to deal with the marmots.\n\nWould you lend him a hand? With rampant hozen and virmen attacks, I can't afford to lose crops to simple pests.", completion = "Well, good. That that's taken care of. Neatly done, {race}.", objectives = "Speak with Wika-Wika, then stomp on 25 Black-Nose Marmots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30320] = { id = 30320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Spirits", description = "I came upon one of the Shao-Tien Soul-Render's daggers. It radiates a strong magic. I've been told it should allow you to enter their spirit vortexes.\n\nThe mogu use these to harvest spirits and bind them to their will, but I'm hoping you can use it to free the spirits.\n\nEnter any of the spirit vortexes you can find up on the Golden Stair, and free all the captive spirits you find.", completion = "Very good! I'll hold onto this dagger. Perhaps we will get the chance to make more use of it later.\n\nThank you so much, my friend. You have a good heart.", objectives = "Enter Spirit Vortexes and free 15 pandaren spirits inside.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30321] = { id = 30321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weed War II", description = "Ssshhay... d'you know that guy over on the farm, with the... the *hic*... the weed problem? Gai Lan, I think his name was. I love that guy, man.\n\nAnywayshh, he said that if I *hic* sent an adventurer over to go pick his weeds, he'd get me some ale.\n\nIt's jusht a few weeds, not too many, probably.\n\n*hic*", completion = "Thanks, mishter *hic* {name}.", objectives = "Speak to Gai Lan, then pick 100 Weeds on his farm. You can pick Weeds while mounted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30322] = { id = 30322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Money Matters", description = "I love working in the market, although there's one aspect of this job I really dislike: collecting debts.\n\nWhile most pandaren debts are simply due to laziness, there are a few unsavory characters around town who simply don't want to pay, and there's some who are just too poor.\n\nA few people here in town owe me money. Could you go talk to them, and remind them about what they owe?", progress = "You know, it's kind of nice having a thug... er, I mean, {class}... like you around.", completion = "I'm glad that nasty business is over with. Nobody gave you any trouble, did they?", objectives = "Obtain Spicemaster Jin Jao's Payment, Trader Jambeezi's Payment, Innkeeper Lei Lan's Payment, and Lolo Lio's payment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30323] = { id = 30323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Don't Even Wear Them", description = "A few weeks ago, a group of those jumpy little Springtail virmen broke into my lockbox and stole several handfuls of my jewelry. I've since found a few pieces, but they still have most of my collection.\n\nIf you're headed up to the Springtail Crag, in the cliffs to the north, you should keep an eye out for them. I'd love to get my jewelry back.", progress = "Can you believe how irresponsible and juvenile those virmen are? Don't they know how much that jewelry COST?", completion = "Oh, {name}! I'd kiss you right here and now if you weren't... well, if you weren't covered in virmen dust.\n\nThanks, though!", objectives = "Obtain a Stolen Circlet, a Ransacked Ring, and a Burglarized Bracelet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30324] = { id = 30324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not in Chee-Chee's Backyard", description = "Not all hozen are the same. Chee-Chee's tribe was forest hozen... came from Jade Forest. Pretty easy to get along with.\n\nThe Kunzen invaders... they come from mountains, far to the north. Not nearly as nice as Chee-Chee.\n\nThey come into our green land, take our things, leave big mess behind.\n\nChee-Chee wants to kill them. You like to help?", completion = "Great! Chee-Chee knew you could do it!", objectives = "Kill 8 members of the Kunzen tribe in the Kunzen Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30325] = { id = 30325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where It Counts", description = "I've been watching those Kunzen hozen, and I've noticed a consistent pattern. Whenever they're getting ready to attack, they participate in strange, barbaric rituals around their totem.\n\nIf we can disrupt this ritual, not only will we put off any impending attacks, we can deal a huge blow to their morale! So get in there, rough them up, and make as much of a mess as possible!", progress = "What are you waiting for? Get up there and have some fun!", completion = "Hah! They'll be cleaning that mess up for days.", objectives = "Throw 8 Kunzen Ritual Candles, kick 4 Blazing Embers, and slay 1 Kunzen Ritualist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30326] = { id = 30326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kunzen Legend-Chief", description = "I've heard people talk about the hozen like they're just some tribe of barely-functional idiots... but that's not true! They have brains, too - they just don't all like to use them that much.\n\nI've heard that the Kunzen tribe has two chiefs - one in charge of fighting, and one in charge of stories, lore, and history.\n\nWhat I wouldn't give to see what kind of stories they tell...", progress = "I'll bet hozen legends aren't that much different than our own.", completion = "Wow! Look at this! It's...\n\n<Fish flips through the pages, and her face sours.>\n\nOh, I think that's a dirty picture. But the rest of this is very interesting! I just love learning how other creatures think. Thanks, {name}!", objectives = "Obtain a Kunzen Legend-Book from a Kunzen Legend-Chief.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30327] = { id = 30327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Have to Burn the Ropes", description = "I, umm... well...\n\nOh, never mind. It was a stupid idea.\n\nIt's just that, I was thinking that maybe we can stop the Kunzen hozen from attacking us without having to, you know... KILL anything. I noticed a few ropes on the side of the mountain. I think they're using them to climb down to our farms and...\n\nNo, forget it. It was a silly idea anyways.", completion = "<Ella's face lights up.>\n\nYou did it? For me? Oh, thank you, thank you, thank you, thank you!", objectives = "Burn 6 Kunzen Ropes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30328] = { id = 30328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thousand-Year Dumpling", description = "One of my most popular recipes is the Thousand-Year Dumpling, which is filled with preserved vegetables.\n\nI normally let the vegetables ferment in a hole underneath my house, but when I looked for them this morning, they were gone!\n\nI blame those thieving virmen.\n\nBring them back, and I'll let you help me cook!", progress = "Try not to open any of the jars. If you do open one, you might not want to smell it too closely.", completion = "Now, my student, lean in closely. Let me show you the secret of the Thousand-Year Dumpling...", objectives = "Obtain 7 jars of Preserved Vegetables.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30329] = { id = 30329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cindergut Peppers", description = "A certain few pandaren around here prefer their dishes unbearably spicy. Unfortunately, my access to such peppers is limited.\n\nThe Kunzen hozen, in the mountains to the west, often carry cindergut peppers. A few of those and I'll be set for a few days.\n\nSay, could you collect some for me? You might want to wear gloves if you'll be handling them directly.", progress = "Just put the peppers down on the cutting board, here. I'd prefer not to touch them myself.", completion = "I don't know how the hozen manage to carry these things on their bodies... let alone eat the things.", objectives = "Obtain 4 Cindergut Peppers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30330] = { id = 30330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truffle Shuffle", description = "I like to bake with truffles... when I can find them. They only grow up on the Skyrange, and in very, very scarce amounts.\n\nThey're a fantastic ingredient, but we can't risk over-farming them. That's why we need to replace what we've taken. Bring me a handful of adult truffles, and plant some of these spores in their place.", progress = "We won't need many truffles. They're for flavor only, really.", completion = "These will do nicely.\n\nNow, {name}... stand closer. Let me show you a thing or two about baking...", objectives = "Obtain 8 Shadelight Truffles, and plant 8 Shadelight Spores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30331] = { id = 30331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mile-High Grub", description = "Have you ever tried Mushan Tail Stew? Chances are, if you have, that it was stringy and tasteless. You see, there's a trick to making the perfect Mushan Tail Stew: you need to cook it at high elevation.\n\nI've already gathered the ingredients. Take this pot up to the Kunzen Village, up in the mountains to the west, and prepare the stew over their bonfire.", progress = "I used to make daily trips into the mountains, just to practice making this stew.\n\nI was younger, then.", completion = "This is fantastic! You are quite the aspiring cook, {race}.", objectives = "Prepare 20 bowls of Mushan Tail Stew over the bonfire in the Kunzen Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30332] = { id = 30332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fatty Goatsteak", description = "You know what? I think I want to grill up some goatsteak today.\n\nNo, not from the puny little shaghorns they keep around here. They don't have nearly enough fat on them.\n\n<The chef pats his voluminous belly.>\n\nYou think I got to this size eating no-fat-havin' goats?\n\nNow, the shaghorns up on the Skyrange, to the west... those'll do just fine.", progress = "<The chef is busy preparing spices and sauces for his imminent steaks.>", completion = "Good choice of steaks, {name}. You've got a future as a butcher. You probably make a better {class}, though.", objectives = "Obtain 4 Fatty Goatsteaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30333] = { id = 30333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesser of Two Evils", description = "Like any farming community, we have the occasional virmen troubles.\n\nThe most powerful Springtail virmen live high up in the cliffs to the north, and only come down when they run out of veggies to nibble on.\n\nFrankly, I've dealt with virmen before. They're nothing but a pest that must be kept in check, and there's no better way to do that than by killing their warren-mother. Easy as that.", progress = "I've had plenty of experience with virmen in the past. Just show them you're stronger than they are, and they'll back off.", completion = "There, that's done with. Now we shift our focus back to farming, for a change.", objectives = "Slay the Springtail Warren-Mother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30334] = { id = 30334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing is Bad... Re-Stealing is OK", description = "The hozen, up in the mountains to the west, continue to steal vegetables from my fellow farmers. Being so close to Halfhill, I very rarely suffer hozen attacks, but my friends have not been so lucky.\n\nSeems to me like they steal way more than they can eat. If you can find any intact vegetables up there in those mountains... steal them back!", progress = "Have you got them?", completion = "Thanks! I'll make sure these are distributed out to my fellow farmers.", objectives = "Re-steal 16 Stolen Vegetables.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30335] = { id = 30335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalling the Ravage", description = "The Kunzen hozen, up in the mountains to the west, have been acting up, lighting their fires and shouting their chants. Based on what I've heard and seen around here, that means that a ravage is coming.\n\nThere's not much we can do to stop the ravage, but we can at least thin their numbers before they attack.", progress = "The ravage could come any time now. We have to be prepared.", completion = "They'll be attacking, but my farm - and the farms of my friends - should not be in any danger.\n\nNot if we can help it, anyways. Right, {name}?", objectives = "Slay 12 Kunzen Hozen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30336] = { id = 30336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kunzen Hunter-Chief", description = "From what I've gathered, the Kunzen hozen have two chiefs. One is harmless - he deals with potions, medicines, and ancient fables. The other one is in charge of the Kunzen's hunters - and the only thing they've been hunting lately is our crops.\n\nThe Hunter-Chief is a problem waiting to be solved. I'm sure the local farmers would be grateful if you went up there and, you know, \"took care\" of him.", progress = "Mm-hmm.", completion = "No doubt the hozen will have a big ritual tonight, promoting a new Hunter-Chief.\n\nI'm just happy that my fellow farmers can rest easy in the meantime.", objectives = "Slay the Kunzen Hunter-Chief.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30337] = { id = 30337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simian Sabotage", description = "The hozen steal from us, and we keep stealing our stuff back. It has to stop sometime.\n\n<Farmer Yoon hands you a barrel of fireworks.>\n\nFind some of our stolen supplies in their mountain camp to the west, and place these fireworks beside them. Hopefully, if they see the explosions, they'll think our supplies are defective and stop stealing altogether.\n\nIt's worth a shot, right?", progress = "Good luck up there, {name}.", completion = "Hopefully they're put off from stealing any more of our supplies. I know I personally wouldn't want to drink any explosive beer, or use an explosive rake.", objectives = "Use the Barrel of Fireworks near the Pile of Stolen Weapons, the Pile of Stolen Tools, the Pile of Stolen Beer, and the Pile of Stolen Grain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30338] = { id = 30338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Weighty Task", description = "For the life of me, I can't figure out why the mogu would have built all their statues and such down in that lake. I'm sure there wasn't always water down there, but it still seems wickedly inconvenient should it ever have rained.\n\nAh well, who's to fathom the strange intentions of the mogu...\n\nWould you be so kind as to swim down there and bring back any artifacts that seem even vaguely carry-able? I'd certainly appreciate it.", progress = "Have you find a pretty stone thing or two for me? I have a hug waiting for you should you have been so kind!", completion = "Well look at you! Not only can you swim in all that very ornate and heavy-looking gear, you can carry half-a-dozen awkwardly large gilded weapons while you do it! Of all your feats, this is surely one of the most impressive, no?\n\nThank you, you marvelously adept swimmer you.", objectives = "Recover 8 Mogu Artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30339] = { id = 30339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting your Hands Dirty", description = "Some of the best fishin' in all of pandaria in this lake right here. I brought enough brew to last me all day, but I didn't think to bring any bait.\n\nWho can really remember such things?\n\nIf you'd be willing to gather me some bait along the shore, I'd be willin' to think on you favorably when it comes time to price my merchandise. Oh, and I'll pay you too, of course. \n\nHow's that sound?", progress = "So much fishin' in store! I can hardly wait to start my waitin'.", completion = "I like a {race} who isn't too lofty to help a humble merchant out. Thank you.", objectives = "Gather 12 Fresh Whitepetal Worms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30340] = { id = 30340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stick in the Mud", description = "I came out for a beautiful day of fishin', but I didn't think to bring a pole. There are so many things to remember for fishin', I just can't keep it all in my head.\n\nThose reeds along the river look alright for makin' a pole out of. If you'd gather me some number of them, I'd be willin' to think on you favorably when it comes time to price my merchandise. Oh, and I'll pay you too, of course. \n\nHow's that sound?", progress = "So much fishin' in store! I can hardly wait to start my waitin'.", completion = "I like a {race} who isn't too lofty to help a humble merchant out. Thank you.", objectives = "Gather 12 Whitepetal Reeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30341] = { id = 30341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Watchful Eyes", description = "<He looks down at the dead mogu scout at his feet, looks up at you, then points out out down the lake shore. It seems he wants you to find and kill more of these mogu scouts.>", completion = "<He bows thankfully.>", objectives = "Kill 8 Shao-Tien Surveyors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30342] = { id = 30342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Tongue, Fragile Feet", description = "I was kicking the water for fun again when one of those vicious crocolisks lunged out to try to bite my foot off! Rude! I have proceeded to rest my weary soles a few feet farther from the water, but I already look back on my water-kicking days longingly.\n\nWould you be so kind as to kill a crocolisk or eight for me? I assure you they deserve it for frightening me though.", completion = "Do you hear that, my beautiful feet? You can rest easy now, your water-kicking days have returned!\n\nYou've been oh so lovely, friend. Do share the fruits of your labors and spend a second or two by the water with me someday. We can exchange tales of that one time when you so generously slaughtered a ravaging band of vicious limb-snatching reptiles for the sake of my frightened and innocent feet. What a grand day that was.", objectives = "Kill 6 Stillwater Crocolisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30343] = { id = 30343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Waterline!", description = "This is Sky-Reaver Stormhowl, captain of the airship Fist of Garrosh and commander of this operation.\n\nYour first task is to burn the 7th Fleet to the waterline while it's still at anchor\n\nCaptain Drok's marines will hold the harbor entrance while your team works.\n\nRig powder barrels in the hold of every ship and then regroup at the harbor entrance to inform Blastmaster Sparkfuse, who will trigger the exposives and signal the airship forward.", objectives = "Rig powder barrels in the hold of all six ships.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30344] = { id = 30344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Dynasty", description = "I wonder if I could bother you for another task. My daughter, the good Sentinel Commander Lyalia here, refuses to let me go into the field.\n\nI have spent everyday in that oubliette staring at the ruins to our north, itching to investigate.\n\nIf we are where I suspect we are those ruins could contain the key we need to finding the fabled Pools of Youth!\n\nPlease, {class}! Go to those ruins and salvage any tablets that still have writing on them.", progress = "It is one thing to research the lost dynasties. It is quite another to visit their ancient ruins.\n\nI am giddy as I have not felt in centuries!", completion = "Oh! Fabulous! Fabulous!\n\nYour one trip has advanced my research more than ten years of reading dusty tomes and decaying scrolls...\n\nAnd those \"mogu\" you saw. I have been doing some research as well as speaking to Kang on the subject.\n\nI suspect now that they were the race of the lost dynasties that my research is derived from.\n\nOf course, that also means that they are the ones who used to control the Pools of Youth.", objectives = "Obtain 6 Dynastic Tablets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30345] = { id = 30345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poisoned!", objectives = "Gather 5 Mogu Poisoned Blades from Mogu Reavers in the Lost Dynasty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30346] = { id = 30346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where are the Pools", description = "Perhaps these mogu know where the pools are.\n\nOur scouts have reported seeing a commander along the southern side of the Ruins of Dojan.\n\nKill him and take whatever information he is carrying. They should lead you to the pool.", progress = "<You sense the presence of Lorekeeper Vaeldrin, then hear his voice within your mind.>\n\nHmm. I'm still not sure about these references to \"torture\" regarding the Pools of Youth.", completion = "Well done, {name}. Hmm, it looks like the mogu are here to collect ancient relics and weapons from their forgotten dynasty. That is a problem we can face later though.\n\nAh! Here is a reference to the Pools of Youth.", objectives = "Obtain the Dojani Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30347] = { id = 30347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pools of Youth", description = "North! Go north to the Pools of Youth. Get some of the water but be on your guard.\n\nThe mogu list this as a \"high value\" target. Kang Bramblestaff will meet you there if he has not already arrived by your side.", progress = "Nothing like being mortal to give one a sense of urgency.", completion = "You... you found the pools! The waters do exist!\n\nSomething is wrong though. I feel equal parts shadow and light swirling in this vial.", objectives = "Obtain some of the Water of Youth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30348] = { id = 30348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immortality?", description = "Something is... off. The water feels strange.\n\nWhen we arrived here I felt the presence of the Light, strong and vibrant, far to the north.\n\nI thought it would be the Pools of Youth. But this... this water is tainted somehow. Stained with mogu magics.\n\nI think it best I try only a sip and we see what happens.", completion = "Wha... what happened? The water... it... it only transfers life. It will not make new life.", objectives = "Observe Vaeldrin as he tests the water of youth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30349] = { id = 30349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat from Dojan", description = "While you were at the ruins dusting off tablets for my father I lost five scouts to wandering mogu patrols.\n\nThese creatures apparently have little interest in peace and are about as trustworthy as the Horde.\n\nThey are too numerous and we are too weak, however.\n\nGo to the ruins west of here and cull the mogu numbers. They won't be expecting a {class}.", progress = "Kang has been sharing stories with me about these mogu.\n\nApparently ages ago they ruled as emperors subjugating all free races of Pandaria and the surrounding regions. Now they are little more than hoodlums.\n\nTo see these mogu fight though, I suspect they are trying to rekindle some of their older ideals and ambitions.", completion = "Well done, {name}. Another few missions like that and we might have to make you an honorary sentinel.", objectives = "Kill 6 Dojani Reclaimers, 8 Dojani Surveyors, and 4 Dojani Enforcers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30350] = { id = 30350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squirmy Delight", progress = "Mama Bramblestaff always said Squirmy Delight will cure any hunger one way or another.", completion = "Ha! With this I can make a stew potent enough to knock these waifish elves on their feet.", objectives = "Gather 5 Intact Skitterer Glands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30351] = { id = 30351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lotus Tea", description = "The mogu really like their poisons and curses. Mama Bramblestaff always said lotus tea cures any mogu curse.\n\nI saw some imperial lotus plants in the nearby Ruins of Dojan. We should go gather some of their leaves and keep them on hand just in case the mogu get unruly.\n\nAlso, this will give me a chance to introduce my fists to some mogu faces.", progress = "I have never seen the mogu this numerous before. They have always been a nuisance but never this bad.", completion = "That's it! You pick, I punch!", objectives = "Gather 20 Imperial Lotus Leaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30352] = { id = 30352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crane Mastery", description = "Thing about hunting birds is you need ammo - and I ain't got any. Thing about hunting with Nesingwary is you need to prove you can keep your tally and bragging rights up.\n\nCan't hunt, can't brag. And I like bragging so this is no good.\n\nCan I hire you to go kill me some carp hunters? You'll find them up and down the river west of here. There are a bunch of them so don't hesitate to hunt while doing other stuff.", completion = "Fantastic. Only thing that would make this hunting trip more entertaining is a chair. Here is the reward I promised you.", objectives = "Kill 12 Carp Hunters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30353] = { id = 30353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profit Mastery", description = "Two words: Tiger Blood!\n\nThis is gonna sell better than saronite back on the black market. Especially once I finish spreading a rumor about how it makes you all buff and stuff.\n\nAnd this jungle is just full of tigers. Can you round up a few vials of tiger blood for me? I'll cut you in on the scam.", progress = "I like hunting with Nesingwary and all but he's in it for the hunting. I'm in it for the profit, and he doesn't pay us.", completion = "Great! This stuff is gonna make me a mint back in Kalimdor. Here's your cut.", objectives = "Obtain 12 Vials of Tiger Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30354] = { id = 30354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Sister Left Behind", completion = "There are so few of us, it is a great relief to see such help.", objectives = "Rescue 8 captives of the mogu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30355] = { id = 30355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Reclaim", progress = "Every artifact in our possession is one less weapon in mogu hands.", completion = "Well done {name}. You have removed the sword from the child's hands.", objectives = "Recover 10 Mogu Artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30356] = { id = 30356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sever Their Supply Line", description = "The mogu reclaimers are using portals to connect to Kun-Lai Summit, bringing in reinforcements and supplies.\n\nWhat is worse, they are sending their captives through these portals.\n\nGo to the Ruins of Korja and destroy as many of these Korjan Reclaimers as you can find.", completion = "You have bought us some much needed breathing room to lick our wounds and prepare a counter-attack.", objectives = "Kill 8 Korjan Reclaimers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30357] = { id = 30357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stoneplow Convoy", progress = "These mantid are a much bigger threat than I think even the pandaren give them credit for.", completion = "It has been a long time since I rolled up my sleeves and helped the needy. In my lust for immortality I forgot why I became a priest.\n\nThank you for reminding me there is good in this world worth fighting for, {name}.", objectives = "Use Imperial Lotus Poultice on 7 Stoneplow Envoys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30358] = { id = 30358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gryphon, Down", description = "The Fist of Garrosh will hold position over the harbor until all other threats from the ground are eliminated.\n\nYour next target: Baldruc, Theramore's gryphon master. That mad dwarf and his beasts can't be allowed to attack the airship from above.\n\nSlay Baldruc, along with his winged charges.", objectives = "Slay Baldruc and his gryphons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30359] = { id = 30359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord Reclaimer", progress = "Lyalia is the only family I have left. I had to bury her mother during the war of Ahn'Qiraj.", completion = "Thank you for avenging my daughter. I am not willing to let her stay dead however.\n\nI still have the waters of youth.", objectives = "Find Lyalia and kill Groundbreaker Brojai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30360] = { id = 30360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Stoneplow", description = "My father gave me his life. Tyrande gave me her trust. My sentinels gave me their allegiance.\n\nIt is time I repaid them all.\n\nWith Brojai dead we can mop up the remaining mogu. The next threat is the mantid.\n\nGo north to Stoneplow and lend them your help. Tell them I will be bringing what sentinels I can muster to aid in the defense of their city against the mantid.", completion = "Mantid from the south? This is not a good day.", objectives = "Travel to Stoneplow Village in Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30361] = { id = 30361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mantid", description = "The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that.\n\nNow they are preparing to hit Stoneplow.\n\nPlease, {class}, destroy some of these beasts before they get sufficient numbers to flank our home.\n\nIf my cousin, Ambassador Len, is still alive and at our convoy he should be able to reward you for your help.", completion = "Thank you for your help, {class}! I've never seen anybody stand up to the mantid like that before.\n\nWell, other than the Shado-Pan, of course...", objectives = "Kill 10 Ik'thik Mantid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30362] = { id = 30362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanks for Nothing!", description = "The last threat to the airship is Theramore's arsenal of steam tanks.\n\nDestroy any active tanks and set bombs on any unmanned vehicles.", objectives = "Destroy any manned tanks and bomb any unmanned ones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30363] = { id = 30363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going on the Offensive", description = "Ha! So my father just wasted twenty years of our lives on a fool's errand!\n\nI'm taking charge.\n\nWhen Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it.\n\nI want you to look for my scout. I sent her to investigate the Crane Temple but she hasn't returned.\n\nGet her report and rendezvous with us at the Sentinel Basecamp further west.", progress = "Did you find the scout?", completion = "{name}, well timed as usual. It turns out the mogu know how to use portals as well.", objectives = "Get Incursion Sentinel's Report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30364] = { id = 30364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fly, Spy!", description = "The First of Garrosh is going the level Theramore Isle... but not until we free the spy whose intelligence made this operation possible.\n\nEnter Foothold Citadel and slay Captain Evencane for his shackles key.\n\nOur spy, the Sunreaver mage Thalen Songweaver, is being held beneath the barracks.", objectives = "Slay Hedric Evencane and free Thalen Songweaver in Foothold Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30365] = { id = 30365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Chee Chee is Farmhand" }
quests[30366] = { id = 30366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Ella is Farmhand" }
quests[30367] = { id = 30367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Sho is Farmhand" }
quests[30368] = { id = 30368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Old Hillpaw is Farmhand" }
quests[30369] = { id = 30369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Haohan Mudclaw is Farmhand" }
quests[30370] = { id = 30370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Farmer Fung is Farmhand" }
quests[30371] = { id = 30371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Tina Mudclaw is Farmhand" }
quests[30372] = { id = 30372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Fish Fellreed is Farmhand" }
quests[30373] = { id = 30373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Jogu the Drunk is Farmhand" }
quests[30374] = { id = 30374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Gina Mudclaw is Farmhand" }
quests[30375] = { id = 30375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Snakes", description = "The rivers here are crawling with venomous aquatic snakes. Several evacuees were bitten as they fled from the temple, and already some are beginning to succumb to the poison.\n\nWe are administering anti-venom as quickly as possible, but we'll need more venom glands.\n\nI won't ask you to remove the glands in the field - that would take too long. Just bring back the heads and I'll take care of the rest.", objectives = "Gather 6 Murkscale Heads from Murkscale Strikers in Krasarang River.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30376] = { id = 30376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope Springs Eternal", completion = "Finally, some good news. I will send a falcon to Winter's Blossom right away and let them know the Temple of the Red Crane is safe.\n\nBetween the sha outbreak and the increasing aggression of the mantid, our forces are being stretched thin.", objectives = "Speak with Loon Mai in Stoneplow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30377] = { id = 30377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minimum Safe Distance", description = "As soon as you and your companions are clear, we're delivering our payload and reducing Theramore Isle to rubble.\n\nReturn to the Sea Wolf and Captain Drok as soon as possible.", objectives = "Return to the Sea Wolf and report to Captain Drok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30378] = { id = 30378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blastmaster", description = "Regroup at the harbor entrance to inform Blastmaster Sparkfuse of your success.\n\nHe will trigger the powder barrels and signal the airship forward.\n\nMake certain that none of your group is on those ships when they go up!", objectives = "Inform Blastmaster Sparkfuse at the harbor entrance that the powder barrels have been rigged.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
